		public override bool CMD_EFFECT_WaitBallThrow() {
            switch (m_subSequence)
            {
                case 0:
                    if (m_comIsCritical)
                    {
                        PlaySequenceEffect(BtlEff.BTLEFF_ETC_CAPTURE_START_CRI, true);
                        m_subSequence = m_comIsSuccsess ? 6 : 7;
                    }
                    else
                    {
                        PlaySequenceEffect(BtlEff.BTLEFF_ETC_CAPTURE_START, true);
                        m_subSequence = m_comRepeatNum > 0 ? 1 : 5;
                    }
                    break;

                case 1:
                    if (!WaitSequence())
                        return false;

                    PlaySequenceEffect(BtlEff.BTLEFF_ETC_CAPTURE_SEQ1, true);
                    m_subSequence = m_comRepeatNum > 1 ? 2 : 5;
                    break;

                case 2:
                    if (!WaitSequence())
                        return false;

                    PlaySequenceEffect(BtlEff.BTLEFF_ETC_CAPTURE_SEQ2, true);
                    m_subSequence = m_comRepeatNum > 2 ? 3 : 5;
                    break;

                case 3:
                    if (!WaitSequence())
                        return false;

                    PlaySequenceEffect(BtlEff.BTLEFF_ETC_CAPTURE_SEQ3, true);
                    m_subSequence = m_comIsSuccsess ? 4 : 5;
                    break;

                case 4:
                    if (!WaitSequence())
                        return false;

                    PlaySequenceEffect(BtlEff.BTLEFF_ETC_CAPTURE_SUCCESS, false);
                    m_subSequence = 8;
                    break;

                case 5:
                    if (!WaitSequence())
                        return false;

                    PlaySequenceEffect(BtlEff.BTLEFF_ETC_CAPTURE_FAIL_1 + m_comRepeatNum, false);
                    m_subSequence = 9;
                    break;

                case 6:
                    if (!WaitSequence())
                        return false;

                    PlaySequenceEffect(BtlEff.BTLEFF_ETC_CAPTURE_SUCCESS_CRI, true);
                    m_subSequence = 8;
                    break;

                case 7:
                    if (!WaitSequence())
                        return false;

                    PlaySequenceEffect(BtlEff.BTLEFF_ETC_CAPTURE_FAIL_CRI, false);
                    m_subSequence = 9;
                    break;

                case 8:
                    return WaitSequence();

                case 9:
                    if (!WaitSequence())
                        return false;

                    ResetPokemon(m_comTargetPoke[1], 0, SEQ_DEF_MOVETYPE.SEQ_DEF_MOVETYPE_LINER);
                    var pokeModel = GetPokeModel(m_comTargetPoke[1]);
                    if (pokeModel != null)
                        pokeModel.SetVisible(true);

                    ResetDefaultCamera();
                    ResetQualitySettings();
                    return true;
            }

            return false;
        }
