		public bool CheckCanPlayCommandWaitCamera(global::Dpr.SequenceEditor.CommandParam param) {
            int value = -1;

            if (param.TryGetOptionValue(GRP_OPT.GRP_OPT_RULE, out value))
            {
                switch ((GRP_OPT_RULE)value)
                {
                    case GRP_OPT_RULE.GRP_OPT_SINGLE:
                        if (GetBattleRule() != BtlRule.BTL_RULE_SINGLE)
                            return false;
                        break;

                    case GRP_OPT_RULE.GRP_OPT_DOUBLE:
                        if (GetBattleRule() != BtlRule.BTL_RULE_DOUBLE)
                            return false;
                        break;

                    case GRP_OPT_RULE.GRP_OPT_NOT_SINGLE:
                        if (GetBattleRule() == BtlRule.BTL_RULE_SINGLE)
                            return false;
                        break;

                    case GRP_OPT_RULE.GRP_OPT_NOT_WILD_SINGLE:
                        if (GetBattleRule() == BtlRule.BTL_RULE_SINGLE && GetBattleCompetitor() == BtlCompetitor.BTL_COMPETITOR_WILD)
                            return false;
                        break;

                    case GRP_OPT_RULE.GRP_OPT_RAID:
                        if (GetBattleRule() != BtlRule.BTL_RULE_RAID)
                            return false;
                        break;

                    case GRP_OPT_RULE.GRP_OPT_NOT_RAID:
                        if (GetBattleRule() == BtlRule.BTL_RULE_RAID)
                            return false;
                        break;

                    case GRP_OPT_RULE.GRP_OPT_SAFARI:
                        if (GetBattleRule() != BtlRule.BTL_RULE_SAFARI)
                            return false;
                        break;
                }
            }

            if (param.TryGetOptionValue(GRP_OPT.GRP_OPT_TRAINER_NUM, out value))
            {
                switch ((GRP_OPT_TRAINER_NUM)value)
                {
                    case GRP_OPT_TRAINER_NUM.GRP_OPT_ATK_TR1:
                        if (m_iPtrCharacterSystem.GetTrainerModel(BtlvPos.BTL_VPOS_NEAR_2).IsEnable)
                            return false;
                        break;

                    case GRP_OPT_TRAINER_NUM.GRP_OPT_ATK_TR2:
                        if (!m_iPtrCharacterSystem.GetTrainerModel(BtlvPos.BTL_VPOS_NEAR_2).IsEnable)
                            return false;
                        break;

                    case GRP_OPT_TRAINER_NUM.GRP_OPT_DEF_TR1:
                        if (m_iPtrCharacterSystem.GetTrainerModel(BtlvPos.BTL_VPOS_FAR_2).IsEnable)
                            return false;
                        break;

                    case GRP_OPT_TRAINER_NUM.GRP_OPT_DEF_TR2:
                        if (!m_iPtrCharacterSystem.GetTrainerModel(BtlvPos.BTL_VPOS_FAR_2).IsEnable)
                            return false;
                        break;
                }
            }

            if (param.TryGetOptionValue(GRP_OPT.GRP_OPT_POKE_SIZE_VPOS, out value))
            {
                BOPokemon pokeModel;
                switch ((GRP_OPT_POKE_SIZE_VPOS)value)
                {
                    case GRP_OPT_POKE_SIZE_VPOS.GRP_OPT_POKE_SIZE_NEAR1_L:
                        pokeModel = m_iPtrCharacterSystem.GetPokemonModel(BtlvPos.BTL_VPOS_NEAR_1);
                        if (pokeModel == null || !pokeModel.IsEnable || pokeModel.GetSize() != Size.L)
                            return false;
                        break;

                    case GRP_OPT_POKE_SIZE_VPOS.GRP_OPT_POKE_SIZE_NEAR1_UNDER_M:
                        pokeModel = m_iPtrCharacterSystem.GetPokemonModel(BtlvPos.BTL_VPOS_NEAR_1);
                        if (pokeModel == null || !pokeModel.IsEnable || pokeModel.GetSize() >= Size.L)
                            return false;
                        break;

                    case GRP_OPT_POKE_SIZE_VPOS.GRP_OPT_POKE_SIZE_NEAR2_L:
                        pokeModel = m_iPtrCharacterSystem.GetPokemonModel(BtlvPos.BTL_VPOS_NEAR_2);
                        if (pokeModel == null || !pokeModel.IsEnable || pokeModel.GetSize() != Size.L)
                            return false;
                        break;

                    case GRP_OPT_POKE_SIZE_VPOS.GRP_OPT_POKE_SIZE_NEAR2_UNDER_M:
                        pokeModel = m_iPtrCharacterSystem.GetPokemonModel(BtlvPos.BTL_VPOS_NEAR_2);
                        if (pokeModel == null || !pokeModel.IsEnable || pokeModel.GetSize() >= Size.L)
                            return false;
                        break;

                    case GRP_OPT_POKE_SIZE_VPOS.GRP_OPT_POKE_SIZE_FAR1_L:
                        pokeModel = m_iPtrCharacterSystem.GetPokemonModel(BtlvPos.BTL_VPOS_FAR_1);
                        if (pokeModel == null || !pokeModel.IsEnable || pokeModel.GetSize() != Size.L)
                            return false;
                        break;

                    case GRP_OPT_POKE_SIZE_VPOS.GRP_OPT_POKE_SIZE_FAR1_UNDER_M:
                        pokeModel = m_iPtrCharacterSystem.GetPokemonModel(BtlvPos.BTL_VPOS_FAR_1);
                        if (pokeModel == null || !pokeModel.IsEnable || pokeModel.GetSize() >= Size.L)
                            return false;
                        break;

                    case GRP_OPT_POKE_SIZE_VPOS.GRP_OPT_POKE_SIZE_FAR2_L:
                        pokeModel = m_iPtrCharacterSystem.GetPokemonModel(BtlvPos.BTL_VPOS_FAR_2);
                        if (pokeModel == null || !pokeModel.IsEnable || pokeModel.GetSize() != Size.L)
                            return false;
                        break;

                    case GRP_OPT_POKE_SIZE_VPOS.GRP_OPT_POKE_SIZE_FAR2_UNDER_M:
                        pokeModel = m_iPtrCharacterSystem.GetPokemonModel(BtlvPos.BTL_VPOS_FAR_2);
                        if (pokeModel == null || !pokeModel.IsEnable || pokeModel.GetSize() > Size.M)
                            return false;
                        break;
                }
            }

            // Shipped: the trainer-num option is read a second time and compared against 1/2/3 (not GRP_OPT_TRAINER_NUM members).
            if (param.TryGetOptionValue(GRP_OPT.GRP_OPT_TRAINER_NUM, out value))
            {
                switch (value)
                {
                    case 1:
                        break;

                    case 2:
                    case 3:
                        return false;
                }
            }

            if (param.TryGetOptionValue(GRP_OPT.GRP_OPT_STADIUM_SIZE, out value))
            {
                switch ((GRP_OPT_STADIUM_SIZE)value)
                {
                    case GRP_OPT_STADIUM_SIZE.GRP_OPT_STADIUM_SIZE_WIDE:
                        if (m_isFieldIndoor)
                            return false;
                        break;

                    case GRP_OPT_STADIUM_SIZE.GRP_OPT_STADIUM_SIZE_NARROW:
                        if (!m_isFieldIndoor)
                            return false;
                        break;
                }
            }

            return true;
        }
		public override bool FinalizeApp() {
            if (GetMainModule().GetCompetitor(true) == BtlCompetitor.BTL_COMPETITOR_COMM)
            {
                CMD_InitFinishWaitCameraEffect();
                if (!CMD_WaitFinishWaitCameraEffect())
                    return false;
            }

            return finalizeCommon();
        }
		public override bool FinalizeAppForce() {
            CMD_InitFinishWaitCameraEffect();
            if (!CMD_WaitFinishWaitCameraEffect())
                return false;

            return finalizeCommon();
        }
		private bool finalizeCommon() {
            m_isFinalize = true;

            SmartPoint.AssetAssistant.Sequencer.update -= OnUpdate;
            SmartPoint.AssetAssistant.Sequencer.lateUpdate -= OnLateUpdate;

            m_iPtrScreenObject.UnInitialize();
            Mem.Del(ref m_iPtrScreenObject);

            BattleJobSystem.Clear();

            Mem.DelIDisposable(ref m_iPtrSequenceSystem);
            Mem.Del(ref m_iPtrCharacterSystem);
            Mem.Del(ref m_iPtrCameraSystem);
            Mem.Del(ref m_iPtrWeatherSystem);
            Mem.Del(ref m_iPtrBattleGroundEffectSystem);
            Mem.DelIDisposable(ref m_iPtrStatusEffectObserverSystem);
            Mem.Del(ref m_battleDataTable);
            Mem.Del(ref m_defaultPlacementData);
            Mem.DelAry(ref m_comTargetPoke);
            Mem.DelAry(ref m_comTargetDamage);
            Mem.DelAry(ref m_comTargetTrainer);
            Mem.DelAry(ref m_effectBallId);
            Mem.DelAry(ref m_effectBallInfo);
            Mem.Del(ref m_pComWaitFunc);
            Mem.DelIDisposable(ref m_iPtrTaskManager);
            Mem.DelIDisposable(ref m_iPtrTaskManagerLate);
            Mem.DelIDisposable(ref m_pokePinchSound);

            ObjectEntity.ReleaseSealEffectData();
            BattleViewAssetManager.UnInitialize(true);
            MsgWindow.MsgWindowManager.CloseMsg();
            BattleStr.QuitSystem();
            DG.Tweening.Core.Debugger.SetLogPriority(DG.Tweening.LogBehaviour.Default);

            SmartPoint.Rendering.DepthOfField.instance.sensorScale = 1.0f;
            Audio.AudioManager.Instance.EnableUpdateListenerByMainCamera(m_preUpdateAudioListenerByMainCamera);

            if (m_shadowResolutionBackup >= 0)
            {
                QualitySettings.shadowResolution = (ShadowResolution)m_shadowResolutionBackup;
                m_shadowResolutionBackup = -1;
            }

            return true;
        }
		public override bool Initialize() {
            switch (InitializeSequenceState)
            {
                case InitializeSequenceStateType.Unregistered:
                    BattleDebug.LapStopwatch("BattleProc.Activate", "View Initialize Start");
                    SmartPoint.AssetAssistant.Sequencer.update += OnUpdate;
                    SmartPoint.AssetAssistant.Sequencer.lateUpdate += OnLateUpdate;
                    InitializeSequenceState = InitializeSequenceStateType.InitSystem;
                    goto case InitializeSequenceStateType.InitSystem;

                case InitializeSequenceStateType.InitSystem:
                    BattleDebug.StartStopwatch("Initialize");
                    BattleStr.InitSystem(GetMainModule(), GetClientID(), GetBattleContainer());
                    m_isFinalize = false;
                    m_iPtrSequenceSystem = new BattleSequenceSystem(this);
                    m_iPtrCharacterSystem = new BattleCharacterSystem(this);
                    m_iPtrStatusEffectObserverSystem = new BattleStatusEffectObserverSystem(this);
                    InitializeSystem();
                    m_battleDataTable = BattleDataTableManager.Instance.BattleDataTable;
                    m_defaultPlacementData = BattleDataTableManager.Instance.BattleDefaultPlacementData;
                    BattleDebug.StopStopwatch("Initialize", "InitializeSystem");
                    InitializeSequenceState = InitializeSequenceStateType.WaitLoadData;
                    goto case InitializeSequenceStateType.WaitLoadData;

                case InitializeSequenceStateType.WaitLoadData:
                {
                    StartLoadObject();

                    string seqName;
                    var effectData = GetBattleEffectComponentData();
                    if (effectData != null)
                    {
                        seqName = effectData.cmdSeqName;
                        if (string.IsNullOrEmpty(seqName))
                            seqName = m_battleDataTable.GetBattleConstantString(BattleConstantKey.DEFAULT_INTRO_SEQUENCE_FILE);

                        m_attrEffParam.attrEffectID = effectData.effectBattleID;
                        m_attrEffParam.SetStreamLineEffectID(GameManager.currentPeriodOfDay, GetMainModule().GetFieldSituation().bgComponent.effectBattleID);
                        m_attrSoundEvent = effectData.soundEventName;
                    }
                    else
                    {
                        seqName = m_battleDataTable.GetBattleConstantString(BattleConstantKey.DEFAULT_INTRO_SEQUENCE_FILE);
                        m_attrEffParam = BTLV_ATTR_EFF_PARAM.Factory();
                        m_attrSoundEvent = null;
                    }

                    m_iPtrSequenceSystem.LoadSequence(BattleViewDefine.Path.GetSequencePath(seqName), false);
                    InitializeSequenceState = InitializeSequenceStateType.WaitLoadGraphic;
                    goto case InitializeSequenceStateType.WaitLoadGraphic;
                }

                case InitializeSequenceStateType.WaitLoadGraphic:
                    if (!m_isFinishLoadObjects || !m_iPtrSequenceSystem.IsLoadedSequenceFile)
                        return false;

                    StartGround();
                    StartSetup();
                    BattleDebug.StartStopwatch("Initialize");
                    m_iPtrSequenceSystem.StartPreLoad();
                    InitializeSequenceState = InitializeSequenceStateType.SetupData;
                    goto case InitializeSequenceStateType.SetupData;

                case InitializeSequenceStateType.SetupData:
                    if (!m_iPtrSequenceSystem.IsPreLoaded)
                        return false;

                    BattleDebug.StopStopwatch("Initialize", "SequenceSystem.IsPreLoaded");
                    m_iPtrSequenceSystem.SetupPreLoad();
                    m_iPtrSequenceSystem.SetPause(true);

                    for (int i = 0; i < (int)BtlvPos.BTL_VPOS_NUM; i++)
                        ResetTrainer((BtlvPos)i, false);

                    for (int i = 0; i < (int)BtlvPos.BTL_VPOS_NUM; i++)
                        ResetPokemon((BtlvPos)i, 0, SEQ_DEF_MOVETYPE.SEQ_DEF_MOVETYPE_LINER);

                    // The binary never stores InitializeSequenceStateType.Finish here (01c83e98 -> 01c83e9c).
                    goto case InitializeSequenceStateType.Finish;

                case InitializeSequenceStateType.Finish:
                    BattleDebug.LapStopwatch("BattleProc.Activate", "View Initialize Finished");
                    return true;
            }

            return false;
        }
		private void StartLoadObject() {
            bool isLoadedAllCharacter = false;
            bool isLoadedMigawari = false;
            bool isLoadedDigudaStone = false;

            var characterSystem = m_iPtrCharacterSystem;
            var mainModule = GetMainModule();

            bool[] isTrainerSetupFlags = System.Linq.Enumerable.ToArray(System.Linq.Enumerable.Repeat(false, (int)BtlvPos.BTL_VPOS_NUM));
            bool[] isPokemonSetupFlags = System.Linq.Enumerable.ToArray(System.Linq.Enumerable.Repeat(false, (int)BtlvPos.BTL_VPOS_NUM));

            var rule = GetBattleRule();
            isPokemonSetupFlags[(int)BtlvPos.BTL_VPOS_FAR_1] = true;

            if (rule == BtlRule.BTL_RULE_DOUBLE)
            {
                isPokemonSetupFlags[(int)BtlvPos.BTL_VPOS_FAR_2] = true;
                if (mainModule.GetDetailRule() != MainModule.BtlDetailRule.WildMulti)
                    isTrainerSetupFlags[(int)BtlvPos.BTL_VPOS_FAR_1] = true;

                isPokemonSetupFlags[(int)BtlvPos.BTL_VPOS_NEAR_1] = true;
                isPokemonSetupFlags[(int)BtlvPos.BTL_VPOS_NEAR_2] = true;
                isTrainerSetupFlags[(int)BtlvPos.BTL_VPOS_NEAR_1] = true;

                if (IsMultiMode() && mainModule != null)
                {
                    if (mainModule.IsExistClient(2))
                        isTrainerSetupFlags[(int)BtlvPos.BTL_VPOS_NEAR_2] = true;

                    if (mainModule.IsExistClient(3))
                        isTrainerSetupFlags[(int)BtlvPos.BTL_VPOS_FAR_2] = true;
                }
            }
            else
            {
                isPokemonSetupFlags[(int)BtlvPos.BTL_VPOS_NEAR_1] = true;
                isTrainerSetupFlags[(int)BtlvPos.BTL_VPOS_NEAR_1] = true;

                if (GetBattleCompetitor() != BtlCompetitor.BTL_COMPETITOR_WILD)
                {
                    isTrainerSetupFlags[(int)BtlvPos.BTL_VPOS_NEAR_1] = true;
                    isTrainerSetupFlags[(int)BtlvPos.BTL_VPOS_FAR_1] = true;
                }
            }

            BattleDebug.StartStopwatch("Initialize");
            SmartPoint.AssetAssistant.Sequencer.Start(characterSystem.StartLoadAllCharacter(isPokemonSetupFlags, isTrainerSetupFlags, () =>
            {
                isLoadedAllCharacter = true;
                if (isLoadedMigawari && isLoadedDigudaStone)
                    m_isFinishLoadObjects = true;

                BattleDebug.StopStopwatch("Initialize", "StartLoadObject");
            }));

            BattleDebug.StartStopwatch("StartLoadObject");
            SmartPoint.AssetAssistant.Sequencer.Start(characterSystem.StartLoadMigawari(() =>
            {
                isLoadedMigawari = true;
                if (isLoadedAllCharacter && isLoadedDigudaStone)
                    m_isFinishLoadObjects = true;

                BattleDebug.StopStopwatch("StartLoadObject", "StartLoadMigawari");
            }));

            BattleDebug.StartStopwatch("StartLoadObject");
            SmartPoint.AssetAssistant.Sequencer.Start(characterSystem.StartLoadDigudaStone(() =>
            {
                isLoadedDigudaStone = true;
                if (isLoadedAllCharacter && isLoadedMigawari)
                    m_isFinishLoadObjects = true;

                BattleDebug.StopStopwatch("StartLoadObject", "StartLoadDigudaStone");
            }));
        }
		private void StartSetup() {
            SetComTargetReset();

            if (GetBattleRule() != BtlRule.BTL_RULE_RAID)
            {
                if (IsCommMode())
                {
                    m_comTargetPoke[0] = BtlvPos.BTL_VPOS_NEAR_1;
                    m_comTargetPoke[1] = BtlvPos.BTL_VPOS_FAR_1;
                    m_comTargetDamage[0] = BtlvPos.BTL_VPOS_FAR_1;

                    m_effectBallInfo[0] = GetBallInfo(BtlvPos.BTL_VPOS_FAR_1);
                    m_effectBallId[0] = m_effectBallInfo[0].ballId;

                    if (GetBattleRule() == BtlRule.BTL_RULE_DOUBLE)
                    {
                        m_effectBallInfo[1] = GetBallInfo(BtlvPos.BTL_VPOS_FAR_2);
                        m_effectBallId[1] = m_effectBallInfo[1].ballId;

                        if (GetMainModule() != null)
                        {
                            m_effectBallInfo[3] = GetBallInfo(BtlvPos.BTL_VPOS_NEAR_2);
                            m_effectBallId[3] = m_effectBallInfo[3].ballId;
                        }
                    }
                }
                else if (GetBattleCompetitor() != BtlCompetitor.BTL_COMPETITOR_WILD)
                {
                    m_comTargetTrainer[0] = BtlvPos.BTL_VPOS_FAR_1;
                    m_comTargetPoke[0] = BtlvPos.BTL_VPOS_FAR_1;

                    m_effectBallInfo[0] = GetBallInfo(BtlvPos.BTL_VPOS_FAR_1);
                    m_effectBallId[0] = m_effectBallInfo[0].ballId;

                    if (GetBattleRule() == BtlRule.BTL_RULE_DOUBLE)
                    {
                        m_comTargetTrainer[1] = BtlvPos.BTL_VPOS_FAR_2;
                        m_comTargetPoke[1] = BtlvPos.BTL_VPOS_FAR_2;
                        m_comTargetDamage[0] = BtlvPos.BTL_VPOS_FAR_2;

                        m_effectBallInfo[1] = GetBallInfo(BtlvPos.BTL_VPOS_FAR_2);
                        m_effectBallId[1] = m_effectBallInfo[1].ballId;

                        if (GetMainModule() != null)
                        {
                            m_effectBallInfo[3] = GetBallInfo(BtlvPos.BTL_VPOS_NEAR_2);
                            m_effectBallId[3] = m_effectBallInfo[3].ballId;
                        }
                    }
                }
                else
                {
                    m_comTargetPoke[0] = BtlvPos.BTL_VPOS_NEAR_1;
                    m_comTargetPoke[1] = BtlvPos.BTL_VPOS_FAR_1;
                    m_comTargetDamage[0] = BtlvPos.BTL_VPOS_FAR_1;
                }
            }

            m_effectBallInfo[2] = GetBallInfo(BtlvPos.BTL_VPOS_NEAR_1);
            m_effectBallId[2] = m_effectBallInfo[2].ballId;
        }
