		private void StartGround() {
            var connector = GameManager.connector;
            if (connector == null)
                return;

            var fieldSituation = GetMainModule().GetFieldSituation();
            SetBattleReflection(connector.reflectionCamera, fieldSituation.bgComponent.reflectionResolution);

            if (m_shadowResolutionBackup < 0)
            {
                m_shadowResolutionBackup = (int)QualitySettings.shadowResolution;

                var shadowResolution = fieldSituation.bgComponent.shadowResolution;
                if ((uint)shadowResolution <= (uint)ShadowResolution.VeryHigh)
                    QualitySettings.shadowResolution = (ShadowResolution)shadowResolution;
            }

            if (m_skrtModelDict == null)
                return;

            bool isExistNear1 = false;
            bool isSkirtNear1 = false;
            if (m_skrtModelDict.ContainsKey(BtlvPos.BTL_VPOS_NEAR_1))
            {
                isExistNear1 = true;
                isSkirtNear1 = TrainerSystem.GetSkirtGraphicsChara(m_skrtModelDict[BtlvPos.BTL_VPOS_NEAR_1]) != null;
            }

            bool isExistNear2 = m_skrtModelDict.ContainsKey(BtlvPos.BTL_VPOS_NEAR_2);
            bool isSkirtNear = isSkirtNear1;
            if (!isSkirtNear1 && isExistNear2)
                isSkirtNear = TrainerSystem.GetSkirtGraphicsChara(m_skrtModelDict[BtlvPos.BTL_VPOS_NEAR_2]) != null;

            bool isExistFar1 = false;
            bool isSkirtFar1 = false;
            if (m_skrtModelDict.ContainsKey(BtlvPos.BTL_VPOS_FAR_1))
            {
                isExistFar1 = true;
                isSkirtFar1 = TrainerSystem.GetSkirtGraphicsChara(m_skrtModelDict[BtlvPos.BTL_VPOS_FAR_1]) != null;
            }

            bool isExistFar2 = m_skrtModelDict.ContainsKey(BtlvPos.BTL_VPOS_FAR_2);
            bool isSkirtFar = isSkirtFar1;
            if (!isSkirtFar1 && isExistFar2)
                isSkirtFar = TrainerSystem.GetSkirtGraphicsChara(m_skrtModelDict[BtlvPos.BTL_VPOS_FAR_2]) != null;

            if (BattleConnector.BattleFieldObject != null)
                BattleConnector.BattleFieldObject.SetSkirtHideObjectActive(isSkirtNear, !(isExistNear1 && isExistNear2), isSkirtFar, !(isExistFar1 && isExistFar2));
        }
		public void SetBattleReflection(global::UnityEngine.Camera reflectionCamera, int reflectionResolutionStage) {
            if (reflectionCamera == null)
                return;

            if ((uint)reflectionResolutionStage >= 16)
                reflectionResolutionStage = 16;

            reflectionCamera.SetActive(reflectionResolutionStage > 0);
            reflectionCamera.enabled = reflectionResolutionStage > 0;
            reflectionCamera.cullingMask = GetBattleReflectionLayer(reflectionResolutionStage > 0);

            var follower = reflectionCamera.GetComponent<ReflectionCameraFollower>();
            if (follower != null)
                follower.SetCustomResolution(reflectionResolutionStage > 0 ? reflectionResolutionStage * 80 : 0, reflectionResolutionStage > 0 ? reflectionResolutionStage * 45 : 0);
        }
		private int GetBattleReflectionLayer(bool isEnable) {
            if (isEnable)
                return Layer.Character | Layer.Field | Layer.Effect | 1;

            return Layer.Nothing;
        }
