		public override bool CMD_StartMsgTrainer(byte clientID, uint param, bool isKeyWait = false) {
            var messageID = (TrainerMessageID)param;
            GetMainModule().GetClientTrainerMsg(clientID, messageID, out string messageLabel, out string sequenceName);

            bool isEmptySequence = SmartPoint.AssetAssistant.UnityExtensions.StringExtensions.IsNullOrEmpty(sequenceName);
            if (messageID == TrainerMessageID.MESSAGE_LOSE || isEmptySequence)
            {
                m_subSequence = 0;
                GetHUD().CMD_StartMsgTrainer(clientID, param, isKeyWait, false);
            }
            else if (SmartPoint.AssetAssistant.UnityExtensions.StringExtensions.IsNullOrEmpty(messageLabel))
            {
                m_subSequence = 100;
            }
            else
            {
                SetComTargetReset();
                m_comTargetTrainer[0] = GetClientIdToBtlvPos(clientID, 0);
                m_trainerTalkParam.clientId = clientID;
                m_trainerTalkParam.param = param;
                m_trainerTalkParam.isKeyWait = isKeyWait;
                m_subSequence = 10;
                PlaySequenceCore(BattleViewDefine.Path.GetSequencePath(sequenceName), false);
            }

            return true;
        }
