		public override bool CMD_WaitMemberChangeAct() {
            switch (m_subSequence)
            {
                case 0:
                    SmartPoint.AssetAssistant.Sequencer.Start(m_iPtrCharacterSystem.StartLoadPoke(m_comTargetPoke[0], false, null));
                    m_subSequence++;
                    goto case 1;

                case 1:
                {
                    var pokeModel = m_iPtrCharacterSystem.GetPokemonModel(m_comTargetPoke[0]);
                    if (pokeModel == null)
                        return false;

                    pokeModel.SetVisible(false);

                    string seqName = m_battleDataTable.GetBattleConstantString(BattleConstantKey.DEFAULT_MEMBER_CHANGE_ACT_SEQUENCE_FILE);
                    if (GetBattleEnv().GetPokeCon().GetPartyData(m_memberChangeActParam.clientID).GetAliveMemberCount() == UNIQUE_MEMBER_CHANGE_ACT_ARIVE_POKE_CNT)
                    {
                        string trainerSeqName = GetMainModule().GetCliehtTrainerSequence(m_memberChangeActParam.clientID, TrainerSequenceID.SEQUENCE_LAST_POKE_IN);
                        if (!string.IsNullOrEmpty(trainerSeqName))
                            seqName = trainerSeqName;
                    }

                    PlaySequenceCore(BattleViewDefine.Path.GetSequencePath(seqName), false);
                    m_subSequence++;
                    return false;
                }

                case 2:
                    if (!WaitSequence())
                        return false;

                    StartRareSequence(new BtlvPos[] { m_comTargetPoke[0] }, 1, true);
                    m_subSequence++;
                    return false;

                case 3:
                    if (!WaitSequence())
                        return false;

                    m_subSequence++;
                    return false;

                case 4:
                    return true;
            }

            return false;
        }
