		private void CMD_ACT_PokeChangeEffect_StartCore(global::Dpr.Battle.Logic.BtlvPos vpos, global::Dpr.Battle.Logic.BtlEff effId, bool isNoLoad) {
            m_comEffectId = effId;
            m_comIsMigawari = GetPokeModel(vpos).IsVisibleMigawari;

            if (GetPokeModel(vpos).IsDisp)
                m_subSequence = 0;
            else
                m_subSequence = isNoLoad ? 120 : 100;
        }
		private bool CMD_ACT_PokeChangeEffect_WaitCore(bool isGChange) {
            if (m_subSequence >= 100)
                return CMD_ACT_PokeChangeEffect_WaitCore_Skip();

            switch (m_subSequence)
            {
                case 0:
                case 1:
                    m_subSequence = 2;
                    return false;

                case 2:
                    m_subSequence = m_comIsMigawari ? 3 : 6;
                    return false;

                case 3:
                    PlaySequenceEffect(BtlEff.BTLEFF_MIGAWARI_WAZA_BEFORE, false);
                    m_subSequence = 5;
                    return false;

                case 5:
                    if (!WaitSequence())
                        return false;

                    m_subSequence = 6;
                    return false;

                case 6:
                    PlaySequenceEffect(m_comEffectId, false);
                    m_subSequence = 7;
                    return false;

                case 7:
                    if (!WaitSequence())
                        return false;

                    GetHUD().OnHUDEvent(HUDEventID.kPokeChangeEnd, this);
                    m_subSequence = m_comIsMigawari ? 8 : 11;
                    return false;

                case 8:
                    PlaySequenceEffect(BtlEff.BTLEFF_MIGAWARI_WAZA_AFTER, false);
                    m_comIsMigawari = false;
                    m_subSequence = 10;
                    return false;

                case 10:
                    if (!WaitSequence())
                        return false;

                    m_subSequence = 11;
                    return false;

                case 11:
                    return true;
            }

            return false;
        }
		private bool CMD_ACT_PokeChangeEffect_WaitCore_Skip() {
            switch (m_subSequence)
            {
                case 100:
                    new PokeReloadTask(this, m_comTargetPoke[0], m_comTargetPoke[1], () => m_subSequence = 101);
                    m_comIsVisibleTame = m_iPtrCharacterSystem.GetPokemonModel(m_comTargetPoke[0]).IsVisibleTame ? 1 : 0;
                    return false;

                case 101:
                {
                    var pokeModel = GetPokeModel(m_comTargetPoke[0]);
                    pokeModel.IsVisibleTame = m_comIsVisibleTame == 1;
                    pokeModel.IsVisibleMigawari = m_comIsMigawari;
                    pokeModel.SetVisible(true);

                    ResetTrainer((BtlvPos)GetBtlvPosToTrainerIdx(m_comTargetPoke[0]), false);
                    ResetPokemon(m_comTargetPoke[0], 0, SEQ_DEF_MOVETYPE.SEQ_DEF_MOVETYPE_LINER);
                    ResetDefaultCamera();

                    GetHUD().OnHUDEvent(HUDEventID.kPokeChangeEnd, this);
                    m_subSequence = 102;
                    return false;
                }

                case 102:
                    return true;

                case 120:
                    m_subSequence = 102;
                    return false;
            }

            return false;
        }
