		public override void CMD_ACT_Safari_Start(global::Dpr.Battle.Logic.BtlPokePos pokePos, global::Dpr.Battle.Logic.BattleViewBase.SafariCmd safariCmd, int param) {
            var vpos = BtlPosToViewPos(pokePos);
            SetComTargetReset();

            string path = string.Empty;
            m_comTargetPoke[0] = vpos;
            m_comTargetDamage[0] = vpos;
            m_comTargetTrainer[0] = BtlvPos.BTL_VPOS_NEAR_1;
            m_effectBallId[0] = BallId.SAFARIBOORU;

            var cmdData = m_battleDataTable.SafariCmdData[(int)safariCmd];
            switch (safariCmd)
            {
                case SafariCmd.Esa:
                case SafariCmd.Doro:
                    path = BattleViewDefine.Path.GetSequencePath(param == 0 ? cmdData.CmdSeqName : cmdData.CmdCritialSeqName);
                    break;

                case SafariCmd.Yousumi:
                    path = BattleViewDefine.Path.GetSequencePath(cmdData.CmdSeqName);
                    break;
            }

            PlaySequenceCore(path, false);
            m_subSequence = 0;
        }
