		public void SeqComFunc_GetPokeRelativePos(ref global::Dpr.Battle.View.RELARIVE_POKE_OPTION opt, ref global::UnityEngine.Vector3 pRetPos, ref global::UnityEngine.Vector3 pRetRot, ref global::UnityEngine.Vector3 pRetScale, bool isCameraAdjust) {
            pRetPos = Vector3.zero;
            pRetRot = Vector3.zero;
            pRetScale = Vector3.one;

            if (opt.m_node == SEQ_DEF_NODE.SEQ_DEF_NODE_BASE)
            {
                var pokeModel = GetPokeModel(opt.m_vpos);

                Vector3 pos = Vector3.zero;
                Vector3 ofs = Vector3.zero;
                int deg = 0;
                GetDefaultPokePos(opt.m_vpos, ref pos, ref deg);

                if (opt.m_autoRotateModel)
                    pRetRot.y = deg;

                ofs = opt.m_offset;
                if (opt.m_adjustFlip && IsPlayerSide(opt.m_vpos))
                    ofs.x = -ofs.x;

                if (opt.m_autoRotatePos)
                    Mathe.Btlv.RotDegXZ(ref ofs, -deg);

                if (pokeModel != null && pokeModel.IsEnable)
                {
                    Vector3 scale = Vector3.one;
                    float adjustHeight = isCameraAdjust ? pokeModel.GetCamAdjustHeight() : pokeModel.GetAdjustHeight();
                    scale = new Vector3(adjustHeight, adjustHeight, adjustHeight);

                    if (opt.m_adjustScale)
                    {
                        ofs = new Vector3(ofs.x * scale.x, ofs.y * scale.y, ofs.z * scale.z);
                        pRetScale = scale;
                    }
                }

                // Always false inside the BASE branch; the binary re-reads opt.m_node (01c886e8).
                if (opt.m_node == SEQ_DEF_NODE.SEQ_DEF_NODE_INTRO)
                {
                    if (pokeModel != null && pokeModel.IsEnable)
                    {
                        Vector3 centerPos = Vector3.zero;
                        pokeModel.GetNodePositionSequence(SEQ_DEF_NODE.SEQ_DEF_NODE_CENTER, ref centerPos);
                        ofs.y = centerPos.y;
                    }
                }

                pRetPos = pos + ofs;
            }
            else
            {
                var pokeModel = GetPokeModel(opt.m_vpos);
                if (!(pokeModel != null && pokeModel.IsEnable))  // op_Inequality @01c885d0 (brief b066 lesson 5)
                {
                    pRetPos = opt.m_offset;
                    return;
                }

                Vector3 nodePos = Vector3.zero;
                Vector3 ofs = Vector3.zero;
                Vector3 scale = Vector3.one;
                pokeModel.GetNodePositionSequence(opt.m_node, ref nodePos);

                ofs = opt.m_offset;
                if (opt.m_adjustFlip && IsPlayerSide(opt.m_vpos))
                    ofs.x = -ofs.x;

                float adjustHeight = isCameraAdjust ? pokeModel.GetCamAdjustHeight() : pokeModel.GetAdjustHeight();
                scale = new Vector3(adjustHeight, adjustHeight, adjustHeight);

                if (opt.m_autoRotateModel)
                    pRetRot = pokeModel.GetRotationVec();

                if (opt.m_autoRotatePos)
                    Mathe.Btlv.RotDegXZ(ref ofs, -pokeModel.GetRotationVec().y);

                if (opt.m_adjustScale)
                {
                    ofs = new Vector3(ofs.x * scale.x, ofs.y * scale.y, ofs.z * scale.z);
                    pRetScale = scale;
                }

                pRetPos = nodePos + ofs;
            }
        }
		public void SeqComFunc_GetSpecialPos(global::Dpr.SequenceEditor.SEQ_DEF_SPPOS trgType, ref global::UnityEngine.Vector3 retPos, ref global::UnityEngine.Vector3 retRot) {
            retPos = Vector3.zero;
            retRot = Vector3.zero;

            switch (trgType)
            {
                case SEQ_DEF_SPPOS.SEQ_DEF_SPPOS_SELF_FIELD:
                    SeqComFunc_GetPokeFiledPos(ref retPos, ref retRot, m_comTargetPoke[0], true);
                    break;

                case SEQ_DEF_SPPOS.SEQ_DEF_SPPOS_ENEMY_FIELD:
                    SeqComFunc_GetPokeFiledPos(ref retPos, ref retRot, m_comTargetPoke[0], false);
                    break;

                case SEQ_DEF_SPPOS.SEQ_DEF_SPPOS_ENEMY_CENTER:
                {
                    retPos = Vector3.zero;
                    retRot = Vector3.zero;

                    int num = 0;
                    for (int i = 0; i < (int)BtlvPos.BTL_VPOS_NUM; i++)
                    {
                        if (m_comTargetDamage[i] == BtlvPos.BTL_VPOS_ERROR)
                            continue;

                        Vector3 pos = Vector3.zero;
                        int deg = 0;
                        GetDefaultPokePos(m_comTargetDamage[i], ref pos, ref deg);
                        retPos = retPos + pos;
                        num++;
                    }

                    if (num > 1)
                    {
                        retPos.x /= num;
                        retPos.y /= num;
                        retPos.z /= num;
                    }

                    var vPos = m_comTargetPoke[0];
                    Vector3 atkPos = Vector3.zero;
                    int atkDeg = 0;
                    GetDefaultPokePos(vPos, ref atkPos, ref atkDeg);
                    retRot.y = (atkDeg + 180) % 360;
                    break;
                }
            }
        }
		public void SeqComFunc_GetPokeFiledPos(ref global::UnityEngine.Vector3 retPos, ref global::UnityEngine.Vector3 retRot, global::Dpr.Battle.Logic.BtlvPos plater, bool isAttack) {
            retPos = Vector3.zero;
            retRot = Vector3.zero;

            int num = 0;
            for (int i = 0; i < (int)BtlvPos.BTL_VPOS_NUM; i++)
            {
                var vPos = (BtlvPos)i;
                if (!IsPokeExist(vPos))
                    continue;

                var pokeModel = GetPokeModel(vPos);
                if (pokeModel && pokeModel.GetSize() > Size.L)
                    continue;

                if (!(IsPlayerSide(plater) ^ IsPlayerSide(vPos) ^ isAttack))
                    continue;

                Vector3 pos = Vector3.zero;
                int deg = 0;
                GetDefaultPokePos(vPos, ref pos, ref deg);
                retPos = retPos + pos;
                num++;
            }

            if (num > 1)
            {
                retPos.x /= num;
                retPos.y /= num;
                retPos.z /= num;
            }

            Vector3 platerPos = Vector3.zero;
            int platerDeg = 0;
            GetDefaultPokePos(plater, ref platerPos, ref platerDeg);
            retRot.y = isAttack ? platerDeg : (platerDeg + 180) % 360;
        }
		public int SeqComFunc_GetTargetPokeNum(bool isCheck = true) {
            int num = 0;
            for (int i = 0; i < (int)BtlvPos.BTL_VPOS_NUM; i++)
            {
                if (m_comTargetDamage[i] != BtlvPos.BTL_VPOS_ERROR)
                    num++;
            }

            if (num == 0 && isCheck)
                return 1;

            return num;
        }
