		public void SeqComFunc_CalcPokeDir(global::UnityEngine.Vector3 nowPos, global::Dpr.Battle.Logic.BtlvPos trgPoke, global::Dpr.SequenceEditor.SEQ_DEF_NODE trgNode, ref global::UnityEngine.Vector3 retRot, bool isVertical) {
            var pokeModel = GetPokeModel(trgPoke);
            Vector3 trgPos = Vector3.zero;

            if (pokeModel != null && pokeModel.IsEnable)
            {
                pokeModel.GetNodePositionSequence(trgNode, ref trgPos);
            }
            else
            {
                int deg = 0;
                GetDefaultPokePos(trgPoke, ref trgPos, ref deg);
            }

            SeqComFunc_CalcPosDir(nowPos, trgPos, ref retRot, isVertical);
        }
		public void SeqComFunc_CalcPosDir(global::UnityEngine.Vector3 nowPos, global::UnityEngine.Vector3 trgPos, ref global::UnityEngine.Vector3 retRot, bool isVertical) {
            var dir = trgPos - nowPos;

            float rotY = Mathe.Atan2Deg(dir.x, dir.z);
            if (rotY - retRot.y > 180.0f)
                rotY -= 360.0f;
            if (rotY - retRot.y < -180.0f)
                rotY += 360.0f;
            retRot.y = rotY;

            if (isVertical)
            {
                float len = Mathe.Length(dir.x, dir.z);
                retRot.x = -Mathe.Atan2Deg(dir.y, len);
            }
        }
		public void SeqComFunc_MoveRelativePoke(global::Dpr.Battle.View.ITranslationObject iPtrObj, int frame, global::Dpr.Battle.View.RELARIVE_POKE_OPTION opt, bool isTrainer = false) {
            var pokeModel = GetPokeModel(opt.m_vpos);
            if (pokeModel == null || !pokeModel.IsEnable)
                return;

            Vector3 pos = Vector3.zero;
            Vector3 rot = Vector3.zero;
            Vector3 scale = Vector3.one;
            SeqComFunc_GetPokeRelativePos(ref opt, ref pos, ref rot, ref scale, isTrainer);

            if (opt.m_rate != 100)
            {
                pos = (pos - iPtrObj.GetTranslationVec()) * (opt.m_rate * 0.01f);
                pos = iPtrObj.GetTranslationVec() + pos;
            }

            if (opt.m_autoRotateModel)
                iPtrObj.SetRotationVec(rot);

            if (opt.m_adjustScale && !isTrainer)
                iPtrObj.SetScaleOffset(scale);

            Vector3 nowPos = iPtrObj.GetTranslationVec();
            BattleSequenceSystem.SetVectorSelectElem(ref nowPos, ref pos, opt.m_targetElem);

            if (frame == 0)
            {
                iPtrObj.SetTranslationVec(nowPos);
            }
            else
            {
                var task = new TaskVectorControl(iPtrObj.GetTranslationVec(), nowPos, ((EaseFunc)opt.m_moveType).GetEase(), frame, x => iPtrObj.SetTranslationVec(x));
                float startTime = m_iPtrSequenceSystem.CurrentTime;
#if PC_UNLOCKED_FPS
                task.SetStartTime(startTime).SetEndTime(startTime + 1.0f / PcPlatform.PcFrameClock.LogicRate * frame).SetAdvanceMode(Task.AdvanceMode.Time);
#else
                task.SetStartTime(startTime).SetEndTime(startTime + 1.0f / Application.targetFrameRate * frame).SetAdvanceMode(Task.AdvanceMode.Time);
#endif
                m_iPtrTaskManager.RegisterTask(task, true);
            }
        }
		public void SeqComFunc_MoveSpecialPos(global::Dpr.Battle.View.ITranslationObject iPtrObj, int frame, global::Dpr.SequenceEditor.SEQ_DEF_SPPOS trgType, global::UnityEngine.Vector3 ofs, bool isRotate, bool isFlip) {
            Vector3 pos = Vector3.zero;
            Vector3 rot = Vector3.zero;
            SeqComFunc_GetSpecialPos(trgType, ref pos, ref rot);

            BtlvPos vPos;
            switch (trgType)
            {
                case SEQ_DEF_SPPOS.SEQ_DEF_SPPOS_SELF_FIELD:
                    vPos = m_comTargetPoke[0];
                    break;

                case SEQ_DEF_SPPOS.SEQ_DEF_SPPOS_ENEMY_FIELD:
                case SEQ_DEF_SPPOS.SEQ_DEF_SPPOS_ENEMY_CENTER:
                    vPos = m_comTargetDamage[0];
                    break;

                default:
                    vPos = BtlvPos.BTL_VPOS_ERROR;
                    break;
            }

            // Shipped: the flip test's result is never used (01c89588 -> 01c8958c).
            if (isFlip)
                SeqComFunc_IsFlipEffect(vPos, vPos);

            if (iPtrObj == null)
                return;

            if (isRotate)
            {
                Mathe.Btlv.RotDegXZ(ref ofs, -rot.y);
                iPtrObj.SetRotationVec(rot);
            }

            pos = pos + ofs;

            if (frame == 0)
            {
                iPtrObj.SetTranslationVec(pos);
            }
            else
            {
                var task = new TaskVectorControl(iPtrObj.GetTranslationVec(), pos, DG.Tweening.Ease.Unset, frame, x => iPtrObj.SetTranslationVec(x));
                float startTime = m_iPtrSequenceSystem.CurrentTime;
#if PC_UNLOCKED_FPS
                task.SetStartTime(startTime).SetEndTime(startTime + 1.0f / PcPlatform.PcFrameClock.LogicRate * frame).SetAdvanceMode(Task.AdvanceMode.Time);
#else
                task.SetStartTime(startTime).SetEndTime(startTime + 1.0f / Application.targetFrameRate * frame).SetAdvanceMode(Task.AdvanceMode.Time);
#endif
                m_iPtrTaskManager.RegisterTask(task, true);
            }
        }
