		public override void CMD_StartSetup() {
            SetupCommSequence = SetupCommSequenceType.SETUP;
            SetupRaidSequence = SetupRaidSequenceType.SETUP;

            if (GetBattleRule() == BtlRule.BTL_RULE_RAID)
                SetupSequenceState = SetupSequenceStateType.RAID_WAIT;
            else if (IsCommMode())
                SetupSequenceState = SetupSequenceStateType.COMM_WAIT;
            else if (GetBattleRule() == BtlRule.BTL_RULE_SAFARI)
                SetupSequenceState = SetupSequenceStateType.SAFARI_IN;
            else if (GetBattleCompetitor() != BtlCompetitor.BTL_COMPETITOR_WILD)
                SetupSequenceState = SetupSequenceStateType.TRAINER_IN;
            else
                SetupSequenceState = SetupSequenceStateType.WILD_IN;

            // The three status flags are zero-valued in BDSP (mov w1, wzr @01c89f48 / 01c89f90 / 01c89fdc; several
            // BTL_STATUS_FLAG members are 0), so these tests never pass; the member names are not recoverable.
            if (GetMainModule() != null)
            {
                if (GetMainModule().GetSetupStatusFlag((BTL_STATUS_FLAG)0))
                    SetupSequenceState = SetupSequenceStateType.WILD_IN;
                else if (GetMainModule().GetSetupStatusFlag((BTL_STATUS_FLAG)0))
                    SetupSequenceState = SetupSequenceStateType.RAID_WAIT;
                else if (GetMainModule().GetSetupStatusFlag((BTL_STATUS_FLAG)0))
                    SetupSequenceState = SetupSequenceStateType.SIMPLE_IN;
            }

            SmartPoint.AssetAssistant.Sequencer.Start(WaitSetupSequence());
        }
		private global::System.Collections.IEnumerator WaitSetupSequence() {
            SetupLight();
            BattleDebug.StartStopwatch("__WaitSetupSequence__");
            yield return BattleViewCore.Instance.InitializeSystem(this);

            BattleDebug.StopStopwatch("__WaitSetupSequence__", "UI Initialize");
            SetupWeather();

            m_preUpdateAudioListenerByMainCamera = Audio.AudioManager.Instance.IsEnableUpdateListenerByMainCamera();
            Audio.AudioManager.Instance.EnableUpdateListenerByMainCamera(true);

            GetHUD().OnHUDEvent(HUDEventID.kInitial, this);
            BattleConnector.isKeepSetup = false;
            BattleDebug.StopStopwatch("BattleProc.Activate", "Activate - __WaitSetupSequence__");

            switch (SetupSequenceState)
            {
                case SetupSequenceStateType.WILD_IN:
                    StartSetView();
                    RegisterCamera();
                    PlaySequenceStartDemo(true);
                    m_comTargetPoke[0] = BtlvPos.BTL_VPOS_FAR_1;
                    goto case SetupSequenceStateType.WILD_RARE;

                case SetupSequenceStateType.WILD_RARE:
                    while (!WaitSequence())
                        yield return FrameCountType.EndOfFrame.GetYieldInstruction();

                    StartRareSequence(new BtlvPos[] { BtlvPos.BTL_VPOS_FAR_1, BtlvPos.BTL_VPOS_FAR_2 }, 2, true);
                    goto case SetupSequenceStateType.SELF_TRAINER;

                case SetupSequenceStateType.SELF_TRAINER:
                    while (!WaitSequence())
                        yield return FrameCountType.EndOfFrame.GetYieldInstruction();

                    CMD_WaitSetup_ThrowSelf();
                    goto case SetupSequenceStateType.SELF_RARE;

                case SetupSequenceStateType.SELF_RARE:
                    while (!WaitSequence())
                        yield return FrameCountType.EndOfFrame.GetYieldInstruction();

                    StartRareSequence(new BtlvPos[] { BtlvPos.BTL_VPOS_NEAR_1, BtlvPos.BTL_VPOS_NEAR_2 }, 2, true);
                    goto case SetupSequenceStateType.SEQ_WAIT;

                case SetupSequenceStateType.TRAINER_IN:
                    StartSetView();
                    RegisterCamera();
                    PlaySequenceStartDemo(true);
                    goto case SetupSequenceStateType.ENEMY_TRAINER;

                case SetupSequenceStateType.ENEMY_TRAINER:
                    while (!WaitSequence())
                        yield return FrameCountType.EndOfFrame.GetYieldInstruction();

                    CMD_WaitSetup_ThrowEnemy(false);
                    goto case SetupSequenceStateType.ENEMY_RARE;

                case SetupSequenceStateType.ENEMY_RARE:
                    while (!WaitSequence())
                        yield return FrameCountType.EndOfFrame.GetYieldInstruction();

                    StartRareSequence(new BtlvPos[] { BtlvPos.BTL_VPOS_FAR_1, BtlvPos.BTL_VPOS_FAR_2 }, 2, true);
                    goto case SetupSequenceStateType.SELF_TRAINER;

                case SetupSequenceStateType.SEQ_WAIT:
                    while (!WaitSequence())
                        yield return FrameCountType.EndOfFrame.GetYieldInstruction();

                    goto case SetupSequenceStateType.FINISH;

                case SetupSequenceStateType.SIMPLE_IN:
                {
                    var pokeModel = GetPokeModel(m_comTargetDamage[0]);
                    if (pokeModel != null)
                        pokeModel.SetVisible(true);

                    StartSetView();
                    RegisterCamera();
                    PlaySequenceStartDemo(true);
                    goto case SetupSequenceStateType.SIMPLE_WAIT;
                }

                case SetupSequenceStateType.SIMPLE_WAIT:
                    while (!WaitSequence())
                        yield return FrameCountType.EndOfFrame.GetYieldInstruction();

                    goto case SetupSequenceStateType.FINISH;

                case SetupSequenceStateType.COMM_WAIT:
                    while (!CMD_WaitSetup_Comm())
                        yield return FrameCountType.EndOfFrame.GetYieldInstruction();

                    goto case SetupSequenceStateType.FINISH;

                case SetupSequenceStateType.SAFARI_IN:
                    StartSetView();
                    RegisterCamera();
                    PlaySequenceStartDemo(false);
                    goto case SetupSequenceStateType.SAFARI_RARE;

                case SetupSequenceStateType.SAFARI_RARE:
                    while (!WaitSequence())
                        yield return FrameCountType.EndOfFrame.GetYieldInstruction();

                    StartRareSequence(new BtlvPos[] { BtlvPos.BTL_VPOS_FAR_1, BtlvPos.BTL_VPOS_FAR_2 }, 2, true);
                    goto case SetupSequenceStateType.SEQ_WAIT;

                case SetupSequenceStateType.FINISH:
                    for (int i = 0; i < (int)BtlvPos.BTL_VPOS_NUM; i++)
                    {
                        var pokeModel = GetPokeModel((BtlvPos)i);
                        if (pokeModel != null)
                            pokeModel.DisableSleepEye(false);
                    }

                    ResetDefaultCamera();
                    SetVisibleBattleObject(true);

                    if (GetMainModule() != null && GetMainModule().GetSetupStatusFlag(BTL_STATUS_FLAG.BTL_STATUS_FLAG_LEGEND))
                        GetHUD().OnHUDEvent(HUDEventID.kStartWaitCamera, this);

                    SetupSequenceState = SetupSequenceStateType.FINISH;
                    break;
            }
        }
		private void StartSetView() {
            int delayFrame = m_battleDataTable.GetBattleConstantInt(BattleConstantKey.START_DELAY_FADE_CNT);
#if PC_UNLOCKED_FPS
            DG.Tweening.TweenSettingsExtensions.SetUpdate(DG.Tweening.DOVirtual.DelayedCall(1.0f / PcPlatform.PcFrameClock.LogicRate * delayFrame, () =>
#else
            DG.Tweening.TweenSettingsExtensions.SetUpdate(DG.Tweening.DOVirtual.DelayedCall(1.0f / Application.targetFrameRate * delayFrame, () =>
#endif
            {
                SmartPoint.Components.Fader.fadeMode = SmartPoint.Components.Fader.FadeMode.Color;
                SmartPoint.Components.Fader.valid = true;
                SmartPoint.Components.Fader.FadeIn();
            }, true), true);
        }
		private void RegisterCamera() {
            var camera = m_iPtrCameraSystem.GetBattleCamera(SequenceCameraSystem.CameraStateType.Main);
            if (camera != null)
                camera.IsEnabled = true;
        }
		public override bool CMD_WaitSetup() {
            return SetupSequenceState == SetupSequenceStateType.NONE || SetupSequenceState == SetupSequenceStateType.FINISH;
        }
		private void PlaySequenceStartDemo(bool isKeepResource = true) {
			m_sequenceSeq = SequenceSeq.WAIT_LOAD;
			m_seqKeepResource = isKeepResource;
			m_isSoundPlayingFinishCheckInvalid = false;
			m_soundPlayingFinishWaitCount = 0;
		}
		private void StartRareSequence(global::Dpr.Battle.Logic.BtlvPos[] posArr, int arrNum, bool isKeepResource = true) {
            SetComTargetReset();

            int targetNum = 0;
            for (int i = 0; i < arrNum; i++)
            {
                var pokeModel = GetPokeModel(posArr[i]);
                if (pokeModel != null && pokeModel.IsEnable && pokeModel.Entity.GetSimpleParam().isRare)
                {
                    m_comTargetDamage[targetNum] = posArr[i];
                    m_comTargetPoke[targetNum] = posArr[i];
                    targetNum++;
                }
            }

            if (targetNum > 0)
                PlaySequenceEffect(BtlEff.BTLEFF_RARE, isKeepResource);
        }
		private void CMD_WaitSetup_ThrowSelf() {
            SetComTargetReset();

            string seqName = string.Empty;
            switch (GetBattleRule())
            {
                case BtlRule.BTL_RULE_SINGLE:
                case BtlRule.BTL_RULE_SAFARI:
                {
                    m_comTargetPoke[0] = BtlvPos.BTL_VPOS_NEAR_1;
                    m_effectBallInfo[0] = GetBallInfo(BtlvPos.BTL_VPOS_NEAR_1);
                    m_effectBallId[0] = m_effectBallInfo[0].ballId;
                    m_comTargetTrainer[0] = BtlvPos.BTL_VPOS_NEAR_1;

                    var pokeParam = GetViewSrcData(BtlvPos.BTL_VPOS_NEAR_1);
                    if (IsGosanke(pokeParam))
                        seqName = GetGosankeThrowSeq(pokeParam.GetFriendship());
                    else
                        seqName = m_battleDataTable.GetSetupIntroPlaySequenceData(BattleSetupIntroID.THROW_PLAYER_SINGLE).SeqName;

                    var mainModule = GetMainModule();
                    if (mainModule != null)
                    {
                        if (GetBattleCompetitor() == BtlCompetitor.BTL_COMPETITOR_WILD && mainModule.IsTurearukiPokemon(GetViewSrcData(m_comTargetPoke[0])))
                            seqName = m_battleDataTable.GetSetupIntroPlaySequenceData(BattleSetupIntroID.THROW_PLAYER_SINGLE_TUREARUKI).SeqName;
                        else if (!mainModule.IsWazaEffectEnable())
                            seqName = m_battleDataTable.GetSetupIntroPlaySequenceData(BattleSetupIntroID.THROW_PLAYER_SINGLE_FAST).SeqName;
                    }
                    break;
                }

                case BtlRule.BTL_RULE_DOUBLE:
                    m_comTargetPoke[0] = BtlvPos.BTL_VPOS_NEAR_1;
                    m_comTargetPoke[1] = BtlvPos.BTL_VPOS_NEAR_2;
                    m_comTargetDamage[0] = BtlvPos.BTL_VPOS_NEAR_2;

                    m_effectBallInfo[0] = GetBallInfo(BtlvPos.BTL_VPOS_NEAR_1);
                    m_effectBallId[0] = m_effectBallInfo[0].ballId;
                    m_effectBallInfo[1] = GetBallInfo(BtlvPos.BTL_VPOS_NEAR_2);
                    m_effectBallId[1] = m_effectBallInfo[1].ballId;

                    m_comTargetTrainer[0] = BtlvPos.BTL_VPOS_NEAR_1;
                    if (IsFriendExist())
                    {
                        m_comTargetTrainer[1] = BtlvPos.BTL_VPOS_NEAR_2;
                        seqName = m_battleDataTable.GetSetupIntroPlaySequenceData(BattleSetupIntroID.THROW_PLAYER_DOUBLE_EXIST_FRIEND).SeqName;
                    }
                    else
                    {
                        seqName = m_battleDataTable.GetSetupIntroPlaySequenceData(BattleSetupIntroID.THROW_PLAYER_DOUBLE_NOT_EXIST_FRIEND).SeqName;
                    }
                    break;
            }

            PlaySequenceCore(BattleViewDefine.Path.GetSequencePath(seqName), false);
        }
		private void CMD_WaitSetup_ThrowEnemy(bool isComm = false) {
            SetComTargetReset();

            m_comTargetPoke[0] = BtlvPos.BTL_VPOS_FAR_1;
            m_comTargetTrainer[0] = BtlvPos.BTL_VPOS_FAR_1;
            m_effectBallInfo[0] = GetBallInfo(BtlvPos.BTL_VPOS_FAR_1);
            m_effectBallId[0] = m_effectBallInfo[0].ballId;

            BattleSetupIntroID introID;
            if (GetBattleRule() == BtlRule.BTL_RULE_DOUBLE)
            {
                m_comTargetPoke[1] = BtlvPos.BTL_VPOS_FAR_2;
                m_comTargetDamage[0] = BtlvPos.BTL_VPOS_FAR_2;
                m_effectBallInfo[1] = GetBallInfo(BtlvPos.BTL_VPOS_FAR_2);
                m_effectBallId[1] = m_effectBallInfo[1].ballId;

                if (IsMultiMode())
                    m_comTargetTrainer[1] = BtlvPos.BTL_VPOS_FAR_2;

                if (IsMultiMode())
                    introID = isComm ? BattleSetupIntroID.THROW_ENEMY_DOUBLE_IS_MULTI_COMM : BattleSetupIntroID.THROW_ENEMY_DOUBLE_IS_MULTI;
                else
                    introID = isComm ? BattleSetupIntroID.THROW_ENEMY_DOUBLE_COMM : BattleSetupIntroID.THROW_ENEMY_DOUBLE;
            }
            else
            {
                var trainerType = GetMainModule().GetClientTrainerType(GetEnemyClientID(0));
                if ((trainerType == Dpr.Trainer.TrainerType.HERO || trainerType == Dpr.Trainer.TrainerType.HEROINE) && !isComm)
                    introID = BattleSetupIntroID.THROW_ENEMY_SINGLE_HEROINE;
                else
                    introID = isComm ? BattleSetupIntroID.THROW_ENEMY_SINGLE_COMM : BattleSetupIntroID.THROW_ENEMY_SINGLE;
            }

            PlaySequenceCore(BattleViewDefine.Path.GetSequencePath(m_battleDataTable.GetSetupIntroPlaySequenceData(introID).SeqName), true);
            GetHUD().OnHUDEvent(HUDEventID.kBallPlateIn_FarSide, this);
        }
		private bool CMD_WaitSetup_Comm() {
            switch (SetupCommSequence)
            {
                case SetupCommSequenceType.SETUP:
                    SetupCommSequence = SetupCommSequenceType.INTRO;
                    goto case SetupCommSequenceType.INTRO;

                case SetupCommSequenceType.INTRO:
                    StartSetView();
                    RegisterCamera();
                    PlaySequenceStartDemo(true);
                    SetupCommSequence = SetupCommSequenceType.THROW_1ST;
                    return false;

                case SetupCommSequenceType.THROW_1ST:
                    if (!WaitSequence())
                        return false;

                    CMD_WaitSetup_ThrowEnemy(true);
                    SetupCommSequence = SetupCommSequenceType.RARE_1ST;
                    return false;

                case SetupCommSequenceType.RARE_1ST:
                    if (!WaitSequence())
                        return false;

                    StartRareSequence(new BtlvPos[] { BtlvPos.BTL_VPOS_FAR_1, BtlvPos.BTL_VPOS_FAR_2 }, 2, true);
                    SetupCommSequence = SetupCommSequenceType.THROW_2ND;
                    return false;

                case SetupCommSequenceType.THROW_2ND:
                    if (!WaitSequence())
                        return false;

                    CMD_WaitSetup_ThrowSelf();
                    SetupCommSequence = SetupCommSequenceType.RARE_2ND;
                    return false;

                case SetupCommSequenceType.RARE_2ND:
                    if (!WaitSequence())
                        return false;

                    StartRareSequence(new BtlvPos[] { BtlvPos.BTL_VPOS_NEAR_1, BtlvPos.BTL_VPOS_NEAR_2 }, 2, true);
                    SetupCommSequence = SetupCommSequenceType.FINISH;
                    return false;

                case SetupCommSequenceType.FINISH:
                    return WaitSequence();
            }

            return false;
        }
		public override bool CMD_InitStartWaitCameraEffect() {
            // The binary calls BattleViewCore.Instance here and discards it (01c8b200).
            _ = BattleViewCore.Instance;

            if (!m_iPtrCameraSystem.IsPlayWaitCamera)
            {
                m_iPtrCameraSystem.StartWaitCamera();
                m_canChangePinch = true;
                m_iPtrStatusEffectObserverSystem.Play();
                SetEnableMotionWaitB(true);
            }

            return true;
        }
		public override bool CMD_WaitStartWaitCameraEffect() {
            // Both results are discarded in the binary (01c8b7e4 / 01c8b7f0).
            _ = BattleViewCore.Instance;
            _ = m_iPtrCameraSystem.IsPlayWaitCamera;

            GetHUD().OnHUDEvent(HUDEventID.kStartWaitCamera, this);
            return true;
        }
		public override void CMD_InitFinishWaitCameraEffect() {
            var cameraSystem = m_iPtrCameraSystem;
            if (!cameraSystem.IsPlayWaitCamera)
                return;

            cameraSystem.EndWaitCamera();
            ResetAll();

            var fieldObject = BattleConnector.BattleFieldObject;
            if (fieldObject != null)
            {
                var ceilingObjects = fieldObject.CeilingObjects;
                if (!ceilingObjects.IsNullOrEmpty())
                {
                    foreach (var ceilingObject in ceilingObjects)
                        ceilingObject.SetActive(true);
                }
            }

            SetEnableMotionWaitB(false);

            if (cameraSystem.IsPlayedWaitCameraOnce)
            {
                for (int i = 0; i < (int)BtlvPos.BTL_VPOS_NUM; i++)
                {
                    var pokeModel = m_iPtrCharacterSystem.GetPokemonModel((BtlvPos)i);
                    if (pokeModel != null && pokeModel.IsEnable)
                        pokeModel.ChangeAnimStatePoke(BattlePokemonEntity.AnimationState.WaitA01, 0.15f, 0.0f);
                }

                for (int i = 0; i < (int)BtlvPos.BTL_VPOS_NUM; i++)
                {
                    var trainerModel = m_iPtrCharacterSystem.GetTrainerModel((BtlvPos)i);
                    if (trainerModel != null && trainerModel.IsEnable)
                        trainerModel.ResetAnimState();
                }
            }

            m_iPtrStatusEffectObserverSystem.Finish();

            if (!IsAllTaskFinished)
            {
                m_iPtrTaskManager.ForceAllFinished();
                m_iPtrTaskManagerLate.ForceAllFinished();
            }

            ResetCheckCanPlayEffect();
        }
		public override bool CMD_WaitFinishWaitCameraEffect() {
            if (m_iPtrStatusEffectObserverSystem != null && !m_iPtrStatusEffectObserverSystem.IsUnInitialized)
            {
                if (!m_iPtrStatusEffectObserverSystem.IsFinish)
                    return false;

                m_iPtrStatusEffectObserverSystem.Stop();
            }

            if (!IsAllTaskFinished)
                return false;

            if (GetHUD() != null)
                GetHUD().OnHUDEvent(HUDEventID.kEndWaitCamera, this);

            ResetAll();
            return true;
        }
