		public override void CMD_ACT_WazaEffect_Start(global::Dpr.Battle.Logic.BtlPokePos atPokePos, global::Dpr.Battle.Logic.BtlPokePos defPokePos, global::Pml.WazaNo waza, byte wazaType, global::Pml.WazaData.WazaTarget wazaRange, global::Dpr.Battle.Logic.BtlvWazaEffect_TurnType turnType, byte continueCount, bool syncDamageEffect, bool isGShockOccur) {
            m_wazaParam.m_atkPos = atPokePos;
            m_wazaParam.m_defPos = defPokePos;
            m_wazaParam.m_id = waza;
            m_wazaParam.m_range = wazaRange;
            m_wazaParam.m_turnType = turnType;
            m_wazaParam.m_continueCount = continueCount;
            m_wazaParam.m_syncDamageEffect = syncDamageEffect;
            m_wazaParam.m_damageAbout = TypeAffinity.AboutAffinityID.NONE;
            m_wazaParam.m_isGShockOccur = isGShockOccur;
            m_wazaParam.m_setData = true;
            m_wazaParam.m_frame = 0;
            m_wazaParam.m_elaspedTime = 0.0f;
            m_wazaParam.m_enableKeyAdjust = false;
            m_wazaParam.m_isPlayMotion = false;
            m_wazaParam.m_keyDiffFrame = 0;
            m_wazaParam.m_attackMotion = BattlePokemonEntity.AnimationState.Max;
            m_wazaParam.m_startFrame = 0;

            m_subSequence = 0;
            ResetCheckCanPlayEffect();
        }
		public override bool CMD_ACT_WazaEffect_Wait() {
            switch (m_subSequence)
            {
                case 0:
                    if (m_wazaParam.m_syncDamageEffect)
                        return true;

                    StartWazaEffect();
                    m_subSequence++;
                    return false;

                case 1:
                    if (!WaitWazaEffect())
                        return false;

                    m_isStartMsgDisplay = false;
                    return true;
            }

            return false;
        }
		private void StartWazaEffect() {
            WazaSequence = WazaSequenceType.SEQ_SETUP;

            m_comTargetPoke[0] = BtlPosToViewPos(m_wazaParam.m_atkPos);
            if (m_wazaParam.m_defPos == BtlPokePos.POS_NULL)
                m_comTargetPoke[1] = BtlvPos.BTL_VPOS_ERROR;
            else
                m_comTargetPoke[1] = BtlPosToViewPos(m_wazaParam.m_defPos);

            m_comIsMigawari = m_iPtrCharacterSystem.GetPokemonModel(m_comTargetPoke[0]).IsVisibleMigawari;
            if ((m_wazaParam.m_id == WazaNo.DAIBAKUHATU || m_wazaParam.m_id == WazaNo.ZIBAKU) && m_wazaParam.m_turnType == BtlvWazaEffect_TurnType.BTLV_WAZAEFF_JIBAKU_TARGET_DAMAGE)
                m_comIsMigawari = false;

            m_comTargetTrainer[0] = (BtlvPos)GetBtlvPosToPosIdx(m_comTargetPoke[0]);
        }
		private bool WaitWazaEffect() {
            var pokeModel = GetPokeModel(m_comTargetPoke[0]);

            switch (WazaSequence)
            {
                case WazaSequenceType.SEQ_SETUP:
                    // The result is discarded in the binary (01c8ce18); both cheer-sound callees are empty.
                    WAZADATA.IsDamage(m_wazaParam.m_id);
                    WazaSequence = WazaSequenceType.SEQ_MIGAWARI_CHECK;
                    break;

                case WazaSequenceType.SEQ_MIGAWARI_CHECK:
                    if (m_wazaParam.m_id == WazaNo.HENSIN)
                        WazaSequence = WazaSequenceType.SEQ_END;
                    else if (m_comIsMigawari)
                        WazaSequence = WazaSequenceType.SEQ_MIGAWARI_OUT;
                    else
                        WazaSequence = WazaSequenceType.SEQ_CAMERA_PLAY;
                    break;

                case WazaSequenceType.SEQ_MIGAWARI_OUT:
                    if (pokeModel.IsVisibleTame)
                    {
                        PlaySequenceEffect(BtlEff.BTLEFF_MIGAWARI_WAZA_BEFORE, false);
                        WazaSequence = WazaSequenceType.SEQ_MIGAWARI_OUT_UPDATE;
                    }
                    else
                    {
                        pokeModel.SetVisibleMigawari(false);
                        WazaSequence = WazaSequenceType.SEQ_CAMERA_PLAY;
                    }
                    break;

                case WazaSequenceType.SEQ_MIGAWARI_OUT_UPDATE:
                    if (!WaitSequence())
                        return false;

                    WazaSequence = WazaSequenceType.SEQ_CAMERA_PLAY;
                    break;

                case WazaSequenceType.SEQ_CAMERA_PLAY:
                    WazaSequence = WazaSequenceType.SEQ_WAZA_PLAY;
                    break;

                case WazaSequenceType.SEQ_CAMERA_PLAY_START:
                    WazaSequence = WazaSequenceType.SEQ_CAMERA_PLAY_WAIT;
                    break;

                case WazaSequenceType.SEQ_CAMERA_PLAY_WAIT:
                    if (!WaitSequence())
                        return false;

                    WazaSequence = WazaSequenceType.SEQ_WAZA_PLAY;
                    break;

                case WazaSequenceType.SEQ_WAZA_PLAY:
                    StartWazaEffectCore();
                    WazaSequence = WazaSequenceType.SEQ_WAZA_PLAY_WAIT;
                    break;

                case WazaSequenceType.SEQ_WAZA_PLAY_WAIT:
                    if (!WaitSequence())
                        return false;

                    WazaSequence = WazaSequenceType.SEQ_FORMCHANGE;
                    break;

                case WazaSequenceType.SEQ_FORMCHANGE:
                    WazaSequence = WazaSequenceType.SEQ_FORMCHANGE_END;
                    break;

                case WazaSequenceType.SEQ_FORMCHANGE_WAIT:
                    if (!WaitSequence())
                        return false;

                    WazaSequence = WazaSequenceType.SEQ_FORMCHANGE_END;
                    break;

                case WazaSequenceType.SEQ_FORMCHANGE_END:
                    if (m_comIsMigawari)
                    {
                        if (WazaDataSystem.GetHitCountMax(m_wazaParam.m_id) >= 2)
                        {
                            m_comMigawariReserve = true;
                            m_comMigawariReserveTarget = m_comTargetPoke[0];
                            WazaSequence = WazaSequenceType.SEQ_END;
                        }
                        else
                        {
                            WazaSequence = WazaSequenceType.SEQ_MIGAWARI_IN;
                        }
                    }
                    else
                    {
                        WazaSequence = WazaSequenceType.SEQ_END;
                    }
                    break;

                case WazaSequenceType.SEQ_MIGAWARI_IN:
                    if (pokeModel.IsVisibleTame)
                    {
                        PlaySequenceEffect(BtlEff.BTLEFF_MIGAWARI_WAZA_AFTER, false);
                        m_comIsMigawari = false;
                        WazaSequence = WazaSequenceType.SEQ_MIGAWARI_IN_UPDATE;
                    }
                    else
                    {
                        pokeModel.SetVisibleMigawari(true);
                        WazaSequence = WazaSequenceType.SEQ_END;
                    }
                    break;

                case WazaSequenceType.SEQ_MIGAWARI_IN_UPDATE:
                    if (!WaitSequence())
                        return false;

                    WazaSequence = WazaSequenceType.SEQ_END;
                    break;

                case WazaSequenceType.SEQ_END:
                    m_wazaParam.m_setData = false;
                    m_wazaParam.m_syncDamageEffect = false;
                    m_wazaParam.m_id = WazaNo.NULL;
                    return !GetHUD().IsSeqEndWait();
            }

            return false;
        }
