		private bool WaitSequence() {
            if (m_iPtrCameraSystem != null && m_iPtrCameraSystem.IsPlayWaitCamera)
                return true;

            return m_sequenceSeq == SequenceSeq.NONE;
        }
		private void StartWazaEffectCore() {
            SetComTargetReset();

            var atkPos = BtlPosToViewPos(m_wazaParam.m_atkPos);
            SetupWazaTarget(atkPos, BtlPosToViewPos(m_wazaParam.m_defPos), m_wazaParam.m_range);

            // IsGChange is called and its result discarded (01c8d2bc); both G flags end up false.
            _ = GetPokeModel(atkPos).IsGChange;
            m_wazaParam.m_isGShortWaza = false;
            m_wazaParam.m_isDefGPoke = IsDefGPoke();

            if (m_wazaParam.m_turnType == BtlvWazaEffect_TurnType.BTLV_WAZAEFF_INDEX_DEFAULT)
                m_wazaParam.m_turnType = GetUniqWazaSeqTurnType(atkPos, m_wazaParam.m_id, BtlvWazaEffect_TurnType.BTLV_WAZAEFF_INDEX_DEFAULT);

            PlaySequenceWaza(m_wazaParam);

            m_wazaParam.m_enableKeyAdjust = false;
            m_wazaParam.m_frame = 0;
            m_wazaParam.m_elaspedTime = 0.0f;
        }
		private void PlaySequenceEffect(global::Dpr.Battle.Logic.BtlEff no, bool isKeepResource = false) {
			if (!CheckCanPlayEffect(m_comTargetPoke[0], no))
				return;

			var data = m_battleDataTable.FindMiscEffectData(no);
			if (data != null)
				PlaySequenceCore("btlv/waza/sequence/" + data.CmdSeqName, isKeepResource);
		}
