		public override void CMD_ACT_DamageEffectPlural_Start(uint pokeCnt, global::Pml.Battle.TypeAffinity.AboutAffinityID affAbout, byte[] pokeID, global::Pml.Battle.TypeAffinity.AffinityID[] pokeAffinity, global::Pml.WazaNo waza) {
            SetComTargetReset();

            if (!m_wazaParam.m_syncDamageEffect)
            {
                m_comTargetPoke[0] = PokeIDToViewPos(pokeID[0]);
                m_comTargetPoke[1] = PokeIDToViewPos(pokeID[0]);

                for (int i = 0; i < (int)BtlvPos.BTL_VPOS_NUM; i++)
                    m_comTargetDamage[i] = BtlvPos.BTL_VPOS_ERROR;
            }

            int idx = 0;
            for (int i = 0; i < (int)BtlvPos.BTL_VPOS_NUM; i++)
            {
                if (m_comTargetDamage[i] != BtlvPos.BTL_VPOS_ERROR)
                    continue;

                m_comTargetDamage[i] = PokeIDToViewPos(pokeID[idx]);
                idx++;
                if (idx >= pokeCnt)
                    break;
            }

            m_wazaParam.m_damageAbout = affAbout;
            m_subSequence = 0;
        }
