		private bool CMD_ACT_DamageEffect_WaitCore() {
            switch (m_subSequence)
            {
                case 0:
                    if (m_wazaParam.m_syncDamageEffect)
                    {
                        StartWazaEffect();
                        GetHUD().OnHUDEvent(HUDEventID.kDamageEffectStart, this);
                        m_subSequence = 1;
                    }
                    else
                    {
                        m_subSequence = 4;
                    }
                    return false;

                case 1:
                    if (!WaitWazaEffect())
                        return false;

                    GetHUD().OnHUDEvent(HUDEventID.kDamageEffectEnd, this);
                    return true;

                case 2:
                case 3:
                    return false;

                case 4:
                    PlaySequenceEffect(m_wazaParam.m_damageAbout != TypeAffinity.AboutAffinityID.NONE ? BtlEff.BTLEFF_SIMPLE_DAMAGE_NO_SOUND : BtlEff.BTLEFF_SIMPLE_DAMAGE, false);
                    // Empty callee inlined: only the bounds check on m_comTargetDamage[0] survives (01c8e1b8).
                    UpdateCheerSoundOnWazaStart_Damage(m_comTargetDamage[0]);
                    m_subSequence = 5;
                    return false;

                case 5:
                    if (!WaitSequence())
                        return false;

                    return !GetHUD().IsSeqEndWait();

                case 100:
                    return true;
            }

            return false;
        }
		public override void CMD_StartDeadAct(global::Dpr.Battle.Logic.BtlPokePos pokePos, bool isKillCountEffectExist) {
            SetComTargetReset();

            m_comTargetPoke[0] = BtlPosToViewPos(pokePos);
            m_comTargetDamage[0] = BtlPosToViewPos(pokePos);
            m_comTargetTrainer[0] = (BtlvPos)GetBtlvPosToTrainerIdx(m_comTargetPoke[0]);

            m_effectBallInfo[0] = GetBallInfo(BtlPosToViewPos(pokePos));
            m_effectBallId[0] = m_effectBallInfo[0].ballId;

            m_deadActParam.vpos = BtlPosToViewPos(pokePos);
            GetHUD().OnHUDEvent(HUDEventID.kDeadActStart, this);

            // The model is fetched and never used (01c8e928).
            var pokeModel = GetPokeModel(m_comTargetPoke[0]);

            BattleConstantKey seqKey;
            if (GetBattleCompetitor() == BtlCompetitor.BTL_COMPETITOR_WILD && !IsPlayerSide(m_comTargetPoke[0]))
            {
                seqKey = BattleConstantKey.SEQ_PLAY_POKEMON_DEAD_ACT_WILD;
            }
            else if (GetSetupStatusFlag((BTL_STATUS_FLAG)0) && (GetBtlvPosToClientId(m_comTargetPoke[0]) == 2 || GetBtlvPosToClientId(m_comTargetPoke[0]) == 3))
            {
                // The flag is a zero-valued BDSP status flag (mov w1, wzr @01c8e974): the test never passes.
                seqKey = BattleConstantKey.SEQ_PLAY_POKEMON_DEAD_ACT_WILD;
            }
            else
            {
                seqKey = BattleConstantKey.SEQ_PLAY_POKEMON_DEAD_ACT_OTHER;
            }

            PlaySequenceCore(BattleViewDefine.Path.GetSequencePath(m_battleDataTable.GetBattleConstantString(seqKey)), false);
            m_subSequence = 0;
        }
		public override bool CMD_WaitDeadAct() {
            var pokeModel = GetPokeModel(m_comTargetPoke[0]);

            switch (m_subSequence)
            {
                case 0:
                    if (!WaitSequence())
                        return false;

                    m_iPtrCharacterSystem.StartDelete(pokeModel);
                    ResetDefaultCamera();
                    SetVisibleBattleObject(true);
                    m_subSequence++;
                    return false;

                case 1:
                    if (!m_iPtrCharacterSystem.IsFinishDelete(pokeModel))
                        return false;

                    m_subSequence++;
                    return false;

                case 2:
                case 100:
                    return true;
            }

            return false;
        }
