		public override void CMD_AddEffect(global::Dpr.Battle.Logic.BtlEff effectNo) {
            m_comEffectId = effectNo;
            if (effectNo > BtlEff.BTLEFF_MAX)
                return;

            SetComTargetReset();
            m_comTargetPoke[0] = BtlvPos.BTL_VPOS_NEAR_1;
            m_comTargetPoke[1] = BtlvPos.BTL_VPOS_NEAR_1;
            m_comTargetDamage[0] = BtlvPos.BTL_VPOS_NEAR_1;

            if (effectNo == BtlEff.BTLEFF_ZOOM_IN_RESET && m_comMigawariReserve)
            {
                m_comMigawariReserve = false;
                if (!GetPokeModel(m_comMigawariReserveTarget))
                    return;

                if (!GetPokeModel(m_comMigawariReserveTarget).IsDisp)
                    return;

                m_comTargetPoke[0] = m_comMigawariReserveTarget;
                m_comTargetPoke[1] = m_comMigawariReserveTarget;
                m_comTargetDamage[0] = m_comMigawariReserveTarget;
                m_comIsMigawari = false;
                m_comMigawariReserveTarget = BtlvPos.BTL_VPOS_ERROR;
                PlaySequenceEffect(BtlEff.BTLEFF_MIGAWARI_WAZA_AFTER, false);
                return;
            }

            PlaySequenceEffect(effectNo, false);
        }
