		public override void CMD_AddEffectByPos(global::Dpr.Battle.Logic.BtlvPos vpos, global::Dpr.Battle.Logic.BtlEff effectNo) {
            if (vpos == BtlvPos.BTL_VPOS_ERROR)
                return;

            if (effectNo > BtlEff.BTLEFF_MAX)
            {
                m_subSequence = 0xff;
                return;
            }

            SetComTargetReset();
            m_comTargetPoke[0] = vpos;
            m_comTargetPoke[1] = vpos;
            m_comTargetDamage[0] = vpos;
            m_comTargetTrainer[0] = (BtlvPos)GetBtlvPosToTrainerIdx(vpos);
            m_subSequence = 0;

            var pokeModel = m_iPtrCharacterSystem.GetPokemonModel(vpos);
            bool isForcePlay =
                (effectNo >= BtlEff.BTLEFF_RAINBOW && effectNo <= BtlEff.BTLEFF_MOOR) ||
                (effectNo >= BtlEff.BTLEFF_CRITICAL_HIT && effectNo <= BtlEff.BTLEFF_CRITICAL_HIT_KAWAIGARI) ||
                effectNo == BtlEff.BTLEFF_RAID_RELIVE_PARTY || effectNo == BtlEff.BTLEFF_RAID_CHEER;

            if (isForcePlay || (pokeModel && pokeModel.IsEnable && pokeModel.IsDisp))
            {
                PlaySequenceEffect(effectNo, false);

                switch (effectNo)
                {
                    case BtlEff.BTLEFF_USE_ITEM:
                    case BtlEff.BTLEFF_SOUBI_ITEM:
                    case BtlEff.BTLEFF_EAT_NUTS_POKE:
                    case BtlEff.BTLEFF_WEATHER_DAMAGE:
                    case BtlEff.BTLEFF_NOROI:
                    case BtlEff.BTLEFF_SIMETUKERU:
                    case BtlEff.BTLEFF_MAKITUKU:
                    case BtlEff.BTLEFF_HONOONOUZU:
                    case BtlEff.BTLEFF_UZUSIO:
                    case BtlEff.BTLEFF_SUNAZIGOKU:
                    case BtlEff.BTLEFF_MATOWARITUKU:
                    case BtlEff.BTLEFF_G791_SHOCK_TURN:
                    case BtlEff.BTLEFF_SOUBI_ITEM_G:
                    case BtlEff.BTLEFF_USE_ITEM_G:
                    case BtlEff.BTLEFF_EAT_NUTS_POKE_G:
                    case BtlEff.BTLEFF_WEATHER_DAMAGE_G:
                    case BtlEff.BTLEFF_TORABASAMI:
                    case BtlEff.BTLEFF_EG_TURN_HIT:
                    case BtlEff.BTLEFF_CRITICAL_HIT:
                    case BtlEff.BTLEFF_CRITICAL_HIT_PLURAL:
                    case BtlEff.BTLEFF_CRITICAL_HIT_KAWAIGARI:
                        m_subSequence = 100;
                        break;
                }
            }
            else
            {
                if (effectNo == BtlEff.BTLEFF_MIGAWARI_DEAD && pokeModel)
                    pokeModel.SetVisibleMigawari(false);

                m_subSequence = 0xff;
            }
        }
		public override bool CMD_WaitEffectByPos() {
            if (m_subSequence == 100)
                return WaitSequence();

            if (m_subSequence != 0)
                return true;

            if (!WaitSequence())
                return false;

            ResetDefaultCamera();
            return true;
        }
		public override void CMD_AddEffectByDir(global::Dpr.Battle.Logic.BtlvPos vpos_from, global::Dpr.Battle.Logic.BtlvPos vpos_to, global::Dpr.Battle.Logic.BtlEff effectNo) {
            if (effectNo > BtlEff.BTLEFF_MAX)
            {
                m_subSequence = 0xff;
                return;
            }

            SetComTargetReset();
            m_comTargetPoke[0] = vpos_from;
            m_comTargetPoke[1] = vpos_to;
            m_comTargetDamage[0] = vpos_to;
            m_subSequence = 0;

            var pokeModel = GetPokeModel(vpos_from);
            if (pokeModel == null || !pokeModel.IsEnable || !pokeModel.IsDisp)
            {
                m_subSequence = 0xff;
                return;
            }

            if (effectNo == BtlEff.BTLEFF_HIMEU_UNOMISAIRU_KAWAMASU || effectNo == BtlEff.BTLEFF_HIMEU_UNOMISAIRU_PIKATYU)
            {
                m_comIsMigawari = m_iPtrCharacterSystem.GetPokemonModel(m_comTargetPoke[0]).IsVisibleMigawari;
                m_subSequence = 50;
                m_comEffectId = effectNo;
            }
            else
            {
                PlaySequenceEffect(effectNo, false);
                if (effectNo == BtlEff.BTLEFF_YADORIGI)
                    m_subSequence = 100;
            }
        }
		public override bool CMD_WaitEffectByDir() {
            switch (m_subSequence)
            {
                case 50:
                    m_subSequence = m_comIsMigawari ? 51 : 53;
                    return false;

                case 51:
                    PlaySequenceEffect(BtlEff.BTLEFF_MIGAWARI_WAZA_BEFORE, false);
                    m_subSequence = 52;
                    return false;

                case 52:
                    if (!WaitSequence())
                        return false;

                    m_subSequence = 53;
                    return false;

                case 53:
                    PlaySequenceEffect(m_comEffectId, false);
                    m_subSequence = 54;
                    return false;

                case 54:
                    if (!WaitSequence())
                        return false;

                    if (!m_comIsMigawari)
                        return true;

                    m_subSequence = 55;
                    return false;

                case 55:
                    PlaySequenceEffect(BtlEff.BTLEFF_MIGAWARI_WAZA_AFTER, false);
                    m_comIsMigawari = false;
                    m_subSequence = 56;
                    return false;

                case 56:
                case 100:
                    return WaitSequence();
            }

            if (m_subSequence != 0)
                return true;

            if (!WaitSequence())
                return false;

            ResetDefaultCamera();
            return true;
        }
		public override void CMD_AddEffectBySide(global::Dpr.Battle.Logic.BtlvPos vpos_from, global::Dpr.Battle.Logic.BtlvPos vpos_to, global::Dpr.Battle.Logic.BtlEff effectNo) {
            if (effectNo > BtlEff.BTLEFF_MAX)
