            m_comTargetDamage[0] = vpos_to;

            var targetBtlPos = ViewPosToBtlPos(m_comTargetPoke[1]);
            int idx = 1;
            for (int i = 0; i < (int)BtlvPos.BTL_VPOS_NUM; i++)
            {
                var btlPos = ViewPosToBtlPos((BtlvPos)i);
                if (btlPos != BtlPokePos.POS_NULL && targetBtlPos != btlPos && GetMainModule().IsFriendPokePos(targetBtlPos, btlPos))
                    m_comTargetDamage[idx++] = (BtlvPos)i;
            }

            m_subSequence = 0;
            PlaySequenceEffect(effectNo, false);

            if (effectNo == BtlEff.BTLEFF_RAIDBOSS_KILL_4)
                m_isFinalizeFadeSkip = true;
