		private void PlaySequenceCore(string path, bool keepResource = false) {
            m_playingSeqFileNameHash = System.IO.Path.GetFileNameWithoutExtension(path);
            m_sequenceSeq = SequenceSeq.SEQ_LOAD_START;
            m_seqKeepResource = keepResource;
            m_iPtrSequenceSystem.LoadSequence(path, () => m_sequenceSeq = SequenceSeq.START_LOAD, false);
        }
		private void PlaySequenceWaza(global::Dpr.Battle.View.Systems.BTLV_WAZA_EFF_PARAM param) {
            bool? isNormalSeq = null;
            PlaySequenceCore(GetWazaSequencePath(ref param, ref isNormalSeq), false);
        }
		private string GetWazaSequencePath(ref global::Dpr.Battle.View.Systems.BTLV_WAZA_EFF_PARAM param, ref global::System.Nullable<bool> isNormalSeq) {
            WazaNo wazaNo = param.m_id;
            BtlvWazaEffect_TurnType turnType = param.m_turnType;
            string seqName = string.Empty;

            _ = GWaza.IsGWaza(wazaNo);
            _ = WAZADATA.GetDamageType(wazaNo);
            _ = GetPokeModel(BtlPosToViewPos(param.m_atkPos)).IsGChange;

            var data = m_battleDataTable.BattleWazaData[(int)wazaNo];

            if (!isNormalSeq.HasValue)
                isNormalSeq = new bool?(false);

            bool isTurnSeq = false;
            switch (turnType)
            {
                case (BtlvWazaEffect_TurnType)0:
                    if (!string.IsNullOrEmpty(data.NotShortenTurnType0))
                        return BattleViewDefine.Path.GetSequencePath(data.NotShortenTurnType0);
                    break;

                case (BtlvWazaEffect_TurnType)1:
                    if (!string.IsNullOrEmpty(data.NotShortenTurnType1))
                        return BattleViewDefine.Path.GetSequencePath(data.NotShortenTurnType1);

                    if (!string.IsNullOrEmpty(data.TurnType1))
                    {
                        seqName = data.TurnType1;
                        isTurnSeq = true;
                    }
                    break;

                case (BtlvWazaEffect_TurnType)2:
                    if (!string.IsNullOrEmpty(data.TurnType2))
                    {
                        seqName = data.TurnType2;
                        isTurnSeq = true;
                    }
                    break;

                case (BtlvWazaEffect_TurnType)3:
                    if (!string.IsNullOrEmpty(data.TurnType3))
                    {
                        seqName = data.TurnType3;
                        isTurnSeq = true;
                    }
                    break;

                case (BtlvWazaEffect_TurnType)4:
                    if (!string.IsNullOrEmpty(data.TurnType4))
                    {
                        seqName = data.TurnType4;
                        isTurnSeq = true;
                    }
                    break;
            }

            if (isNormalSeq.HasValue)
                isNormalSeq = new bool?(true);

            if (!isTurnSeq)
                seqName = data.CmdSeqName;

            return BattleViewDefine.Path.GetSequencePath(seqName);
        }
		private bool IsWazaMsgCommandSeq() {
            if (m_isStartMsgDisplay)
                return false;

            var msgFrameData = m_battleDataTable.FindMsgFrameData(m_playingSeqFileNameHash);
            if (msgFrameData == null)
                return false;

            if (msgFrameData.frame < 0)
                return false;

            if (m_wazaParam.m_continueCount != 0)
                return false;

            return true;
        }
		private void StartWazaMsgCommand() {
            var msgFrameData = m_battleDataTable.FindMsgFrameData(m_playingSeqFileNameHash);
            if (msgFrameData == null)
                return;

            m_wazaMsgFrame = msgFrameData.frame;

            var vpos = m_comTargetPoke[0];
            var hud = GetHUD();
            hud.CMD_StartMsgWaza(GetBattlePokeParam(vpos).GetID(), m_wazaParam.m_id, true);

            m_playingSeqFileNameHash = string.Empty;
        }
		private bool WaitWazaMsgCommand() {
#if PC_UNLOCKED_FPS
            m_wazaMsgFrame -= PcPlatform.PcFrameClock.Ticks;
#else
            m_wazaMsgFrame--;
#endif
            return m_wazaMsgFrame < 0;
        }
		public void OnUpdate(float deltaTime) {
            if (m_isFinalize)
                return;

            if (deltaTime >= 0.2 && IsApplicationPause)
                return;

            UpdateSuspendSequenceSystem();
            UpdateSequence();

            if (!IsSuspendSequenceSystem)
            {
                if (m_iPtrSequenceSystem != null)
                    m_iPtrSequenceSystem.Update(deltaTime, 1);

                if (m_iPtrTaskManager != null)
                    m_iPtrTaskManager.OnUpdate(deltaTime, m_iPtrSequenceSystem.CurrentTime, 1);

                if (m_iPtrCameraSystem != null)
                    m_iPtrCameraSystem.OnUpdate(deltaTime);
            }

            CheckPokePinch();

            if (m_iPtrStatusEffectObserverSystem != null)
                m_iPtrStatusEffectObserverSystem.OnUpdate(deltaTime);

            BattleJobSystem.OnUpdatePreJob(deltaTime);
        }
		public void OnLateUpdate(float deltaTime) {
            if (m_isFinalize)
                return;

            if (IsApplicationPause)
            {
                IsApplicationPause = false;
                if (deltaTime >= 0.2)
                    return;
            }

            if (!IsSuspendSequenceSystem)
            {
                if (m_iPtrSequenceSystem != null)
                    m_iPtrSequenceSystem.LateUpdate(deltaTime);

                if (m_iPtrTaskManagerLate != null)
                    m_iPtrTaskManagerLate.OnUpdate(deltaTime, m_iPtrSequenceSystem.CurrentTime, 1);

                if (m_iPtrCameraSystem != null)
                    m_iPtrCameraSystem.OnLateUpdate(deltaTime);
            }

            BattleJobSystem.OnUpdatePostJob(deltaTime);
        }
		private void UpdateSequence() {
            var sequenceSystem = m_iPtrSequenceSystem;

            switch (m_sequenceSeq)
            {
                case SequenceSeq.START_LOAD:
                    if (sequenceSystem.IsLoadedSequenceFile)
                    {
                        sequenceSystem.SetupSequence();
                        sequenceSystem.StartPreLoad();
                        m_sequenceSeq = SequenceSeq.WAIT_PRELOAD;
                    }
                    break;

                case SequenceSeq.WAIT_PRELOAD:
                    if (sequenceSystem.IsPreLoaded)
                    {
                        sequenceSystem.SetupPreLoad();
                        sequenceSystem.SetPause(true);
                        m_isSoundPlayingFinishCheckInvalid = false;
                        m_soundPlayingFinishWaitCount = 0;
                        m_sequenceSeq = SequenceSeq.WAIT_LOAD;
                    }
                    break;

                case SequenceSeq.WAIT_LOAD:
                    if (IsWazaMsgCommandSeq())
                    {
                        StartWazaMsgCommand();
                        m_sequenceSeq = SequenceSeq.WAIT_WAZA_MSG;
                    }
                    else
                    {
                        sequenceSystem.SetPause(false);
                        m_sequenceSeq = SequenceSeq.UPDATE_SEQUENCE;
                    }
                    break;

                case SequenceSeq.WAIT_WAZA_MSG:
                    if (WaitWazaMsgCommand())
                    {
                        sequenceSystem.SetPause(false);
                        m_sequenceSeq = SequenceSeq.UPDATE_SEQUENCE;
                    }
                    break;

                case SequenceSeq.UPDATE_SEQUENCE:
                    if (!IsSuspendSequenceSystem && sequenceSystem.IsFinishSequence && IsAllTaskFinished)
                    {
                        sequenceSystem.SetPause(true);
                        m_sequenceSeq = SequenceSeq.FINISH;
                    }
                    break;

                case SequenceSeq.FINISH:
                    if (m_seqKeepResource)
                    {
                        m_sequenceSeq = SequenceSeq.NONE;
                        m_seqKeepResource = false;
                        break;
                    }

                    sequenceSystem.DeleteAllVector();
                    m_sequenceSeq = SequenceSeq.SOUND_WAIT;
                    goto case SequenceSeq.SOUND_WAIT;

                case SequenceSeq.SOUND_WAIT:
                    m_sequenceSeq = SequenceSeq.NONE;
                    break;
            }
        }
		private void UpdateSuspendSequenceSystem() {
            if (m_iPtrSequenceSystem == null)
                return;

            if (m_pComWaitFunc != null && m_pComWaitFunc.Invoke())
                m_pComWaitFunc = null;

            m_wazaParam.m_frame = m_iPtrSequenceSystem.CurrentFrame;
            m_wazaParam.m_elaspedTime = m_iPtrSequenceSystem.CurrentTime;

            if (m_iPtrSequenceSystem.IsPause)
                return;

#if PC_UNLOCKED_FPS
            if (m_wazaParam.m_elaspedTime >= 1.0f / PcPlatform.PcFrameClock.LogicRate * m_wazaParam.m_keyDiffFrame && !m_wazaParam.m_isPlayMotion)
#else
            if (m_wazaParam.m_elaspedTime >= 1.0f / Application.targetFrameRate * m_wazaParam.m_keyDiffFrame && !m_wazaParam.m_isPlayMotion)
#endif
            {
                m_wazaParam.m_isPlayMotion = true;

                var vpos = m_comTargetPoke[0];
                if (vpos == BtlvPos.BTL_VPOS_ERROR)
                    return;

                var pokeModel = m_iPtrCharacterSystem.GetPokemonModel(vpos);
                if (pokeModel != null)
                    pokeModel.ChangeAnimStatePoke(m_wazaParam.m_attackMotion, 0.15f, 0.0f);

                return;
            }

            if (!m_wazaParam.m_enableKeyAdjust)
                return;

            if (m_wazaParam.m_keyDiffFrame >= 0)
            {
                m_wazaParam.m_enableKeyAdjust = false;
                return;
            }

#if PC_UNLOCKED_FPS
            m_wazaParam.m_keyDiffFrame += 2 * PcPlatform.PcFrameClock.Ticks;
#else
            m_wazaParam.m_keyDiffFrame += 2;
#endif
        }
		private void CheckPokePinch() {
            if (m_reqCheckPinch)
            {
                for (int i = 0; i < (int)BtlvPos.BTL_VPOS_NUM; i++)
                {
                    var pokeModel = m_iPtrCharacterSystem.GetPokemonModel((BtlvPos)i);
                    if (pokeModel == null || !pokeModel.IsEnable)
                        continue;

                    if (GetHUD().HUD_IsPinch((BtlvPos)i))
                    {
                        if (!pokeModel.GetRTPC_IsPlayPinchSound())
                            pokeModel.SetRTPC_IsPlayPinchSound(true);
                    }
                    else if (pokeModel.GetRTPC_IsPlayPinchSound())
                    {
                        pokeModel.SetRTPC_IsPlayPinchSound(false);
                    }
                }
            }

            if (!m_canChangePinch)
                return;

            bool isPlayPinchSound = false;
            for (int i = 0; i < (int)BtlvPos.BTL_VPOS_NUM; i++)
            {
                var pokeModel = m_iPtrCharacterSystem.GetPokemonModel((BtlvPos)i);
                if (pokeModel == null || !pokeModel.IsEnable)
                    continue;

                if (!IsPlayerSide((BtlvPos)i))
                    continue;

                if (GetHUD().HUD_IsPinch((BtlvPos)i))
                {
                    if (GetHUD().HUD_IsShowing((BtlvPos)i) && !pokeModel.GetIsPlayPinchSound())
                    {
                        pokeModel.SetIsPlayPinchSound(true);
                        isPlayPinchSound = true;
                    }
                }
                else if (pokeModel.GetIsPlayPinchSound())
                {
                    pokeModel.SetIsPlayPinchSound(false);
                }
            }

            if (isPlayPinchSound && !m_pokePinchSound.IsPlaying)
                m_pokePinchSound.PostEvent(null);
        }
