		private void ResetDefaultCamera(int frame, global::Dpr.Battle.View.EaseFunc moveType, global::Dpr.Battle.View.Systems.BattleCameraSystem system) {
            Vector3 pos = Vector3.zero;
            Vector3 target = Vector3.zero;
            float fov = 0.0f;
            float depthNear = 0.0f;
            float depthFar = 0.0f;
            GetDefaultCameraParam(GetPokeSize(BattleViewSide.PLAYER_SIDE, false), GetPokeSize(BattleViewSide.ENEMY_SIDE, false), false, ref pos, ref target, ref fov, ref depthNear, ref depthFar);
            ResetDefaultCameraParam(frame, moveType, system, pos, target, fov, depthNear, depthFar);
        }
		private void ResetDefaultCameraParam(int frame, global::Dpr.Battle.View.EaseFunc moveType, global::Dpr.SequenceEditor.SequenceCameraSystem system, global::UnityEngine.Vector3 pos, global::UnityEngine.Vector3 target, float fov, float depthNear, float depthFar) {
            var camera = system.GetBattleCamera(SequenceCameraSystem.CameraStateType.Main);

            if (SmartPoint.Rendering.DepthOfField.instance != null)
                SmartPoint.Rendering.DepthOfField.instance.sensorScale = GetTimeZoneSensorScale();

            camera.Near = depthNear;
            camera.Far = depthFar;

            if (frame != 0)
            {
                Vector3 pseudoTarget = camera.CalcPseudoTarget(pos, target);
                var task = new TaskCameraMove(camera, pos, pseudoTarget, Vector3.zero, Vector3.zero, fov, moveType.GetEase(), frame);
                float startTime = m_iPtrSequenceSystem.CurrentTime;
#if PC_UNLOCKED_FPS
                task.SetStartTime(startTime).SetEndTime(startTime + 1.0f / PcPlatform.PcFrameClock.LogicRate * frame).SetAdvanceMode(Task.AdvanceMode.Time);
#else
                task.SetStartTime(startTime).SetEndTime(startTime + 1.0f / Application.targetFrameRate * frame).SetAdvanceMode(Task.AdvanceMode.Time);
#endif
                m_iPtrTaskManager.RegisterTask(task, true);
                camera.Twist = 0.0f;
            }
            else
            {
                camera.Fov = fov;
                camera.Twist = 0.0f;
                camera.SetPositionOffset(Vector3.zero);
                camera.SetTargetOffset(Vector3.zero);
                camera.SetPosition(pos, Quaternion.Euler(target));

                if (camera.CameraState == SequenceCameraSystem.CameraStateType.Main)
                    ResetHitBack();
            }

            system.SetCameraAnimationCheckGround(true);
            system.SetCameraPosOverCheck(true);
        }
		private void GetDefaultCamera(ref global::UnityEngine.Vector3 pos, ref global::UnityEngine.Vector3 target, ref float fov, ref float depthNear, ref float depthFar) {
            GetDefaultCameraParam(GetPokeSize(BattleViewSide.PLAYER_SIDE, false), GetPokeSize(BattleViewSide.ENEMY_SIDE, false), false, ref pos, ref target, ref fov, ref depthNear, ref depthFar);
        }
		private void GetDefaultCamera_Target(ref global::UnityEngine.Vector3 pos, ref global::UnityEngine.Vector3 target, ref float fov, ref float depthNear, ref float depthFar) {
            BtlvPos atkPos = m_comTargetPoke[0];
            BtlvPos defPos = m_comTargetDamage[0];

            if (atkPos == BtlvPos.BTL_VPOS_ERROR || defPos == BtlvPos.BTL_VPOS_ERROR ||
                GetBattleRule() == BtlRule.BTL_RULE_SINGLE || GetBattleRule() == BtlRule.BTL_RULE_DOUBLE)
            {
                GetDefaultCameraParam(GetPokeSize(BattleViewSide.PLAYER_SIDE, false), GetPokeSize(BattleViewSide.ENEMY_SIDE, false), false, ref pos, ref target, ref fov, ref depthNear, ref depthFar);
                return;
            }

            Size playerSize = GetPokeSize(BattleViewSide.PLAYER_SIDE, false);
            Size enemySize = GetPokeSize(BattleViewSide.ENEMY_SIDE, false);

            bool isPlayerAtk = IsPlayerSide(atkPos);
            BOPokemon atkModel = m_iPtrCharacterSystem.GetPokemonModel(atkPos);
            BOPokemon playerPoke = isPlayerAtk ? atkModel : null;
            BOPokemon enemyPoke = isPlayerAtk ? null : atkModel;

            int targetNum = SeqComFunc_GetTargetPokeNum(true);
            for (int i = 0; i < targetNum; i++)
            {
                BtlvPos vpos = m_comTargetDamage[i];
                if (vpos == BtlvPos.BTL_VPOS_ERROR)
                    continue;

                BOPokemon model = m_iPtrCharacterSystem.GetPokemonModel(vpos);
                if (IsPlayerSide(vpos))
                {
                    if (playerPoke)
                    {
                        if (model.GetSize() > playerPoke.GetSize())
                            playerPoke = model;
                    }
                    else
                    {
                        playerPoke = model;
                    }
                }
                else
                {
                    if (enemyPoke)
                    {
                        if (model.GetSize() > enemyPoke.GetSize())
                            enemyPoke = model;
                    }
                    else
                    {
                        enemyPoke = model;
                    }
                }
            }

            if (playerPoke)
            {
                playerSize = playerPoke.GetSize();
                if (playerPoke.IsGChange == GState.NONE)
                    playerSize = GetPokeSize(BattleViewSide.PLAYER_SIDE, false);
            }

            if (enemyPoke)
            {
                enemySize = enemyPoke.GetSize();
                if (enemyPoke.IsGChange == GState.NONE)
                    enemySize = GetPokeSize(BattleViewSide.ENEMY_SIDE, false);
            }

            GetDefaultCameraParam(playerSize, enemySize, false, ref pos, ref target, ref fov, ref depthNear, ref depthFar);
        }
		private void GetDefaultCameraParam(global::Pml.PokePara.Size playerSize, global::Pml.PokePara.Size enemySize, bool isExistGPoke, ref global::UnityEngine.Vector3 pos, ref global::UnityEngine.Vector3 target, ref float fov, ref float near, ref float far) {
            var placementData = BattleDataTableManager.Instance.BattleDefaultPlacementData;
            var mainModule = GetMainModule();
            var rule = GetBattleRule();

            // Both tests pass the literal flag 0 (no BTL_STATUS_FLAG member; always false in BDSP, as shipped).
            if (mainModule != null && GetBattleRule() == BtlRule.BTL_RULE_RAID &&
                (mainModule.GetSetupStatusFlag((BTL_STATUS_FLAG)0) || mainModule.GetSetupStatusFlag((BTL_STATUS_FLAG)0)))
                rule++;

            // Size.L = 3 = BTL_RULE_SAFARI (the binary reuses the rule register, csel eq @01c925d8).
            var data = placementData.GetDefaultCameraPlacementData(rule, rule == BtlRule.BTL_RULE_SAFARI ? Size.L : playerSize, enemySize);
            pos = data.MainCamPos;
            target = data.MainCamRot;
            fov = data.MainCamFov;
            near = data.MainCamNear;
            far = data.MainCamFar;
        }
		public float GetTimeZoneSensorScale() {
			PeriodOfDay period = GameManager.currentPeriodOfDay;
			var dataTable = BattleDataTableManager.Instance.BattleDataTable;
			switch (period)
			{
				case PeriodOfDay.Morning:
					return dataTable.GetBattleConstantFloat(global::Dpr.Battle.View.BattleConstantKey.DOF_SENSOR_SCALE_MORNING);
				case PeriodOfDay.Daytime:
					return dataTable.GetBattleConstantFloat(global::Dpr.Battle.View.BattleConstantKey.DOF_SENSOR_SCALE_DAYTIME);
				case PeriodOfDay.Evening:
					return dataTable.GetBattleConstantFloat(global::Dpr.Battle.View.BattleConstantKey.DOF_SENSOR_SCALE_EVENING);
				case PeriodOfDay.Night:
					return dataTable.GetBattleConstantFloat(global::Dpr.Battle.View.BattleConstantKey.DOF_SENSOR_SCALE_NIGHT);
				case PeriodOfDay.Midnight:
					return dataTable.GetBattleConstantFloat(global::Dpr.Battle.View.BattleConstantKey.DOF_SENSOR_SCALE_MIDNIGHT);
			}
			return 1f;
		}
