		public void ResetPokemon(global::Dpr.Battle.Logic.BtlvPos vPos, int frame, global::Dpr.SequenceEditor.SEQ_DEF_MOVETYPE moveType, global::Dpr.SequenceEditor.SEQ_DEF_DEFAULT_PLACEMENT placement = (global::Dpr.SequenceEditor.SEQ_DEF_DEFAULT_PLACEMENT)(0)) {
            Vector3 pos = Vector3.zero;
            Vector3 scale = Vector3.one;
            int deg = 0;

            BattleViewCharacter iPtrPoke = GetPokeModel(vPos);
            if (iPtrPoke == null)
                return;

            GetDefaultPokePos(vPos, ref pos, ref deg, placement);
            Vector3 rot = new Vector3(0.0f, deg, 0.0f);

            if (frame == 0)
            {
                iPtrPoke.SetTranslationVec(pos);
                iPtrPoke.SetRotationVec(rot);
                iPtrPoke.SetScaleVec(scale);
                iPtrPoke.NodeScaleTranslation = Vector3.zero;
                iPtrPoke.NodeRotateTranslation = Vector3.zero;
                return;
            }

            var taskTranslation = new TaskVector4Control(iPtrPoke.GetTranslationVec(), pos, ((EaseFunc)moveType).GetEase(), frame, x => iPtrPoke.SetTranslationVec((Vector3)x));
            var taskRotation = new TaskVector4Control(iPtrPoke.GetRotationVec(), rot, ((EaseFunc)moveType).GetEase(), frame, x => iPtrPoke.SetRotationVec((Vector3)x));
            var taskScale = new TaskVector4Control(iPtrPoke.GetScaleVec(), scale, ((EaseFunc)moveType).GetEase(), frame, x => iPtrPoke.SetScaleVec((Vector3)x));
            var taskNodeScale = new TaskVector4Control(iPtrPoke.GetNodeScaleTranslation(), Vector4.zero, ((EaseFunc)moveType).GetEase(), frame, x => iPtrPoke.SetNodeScaleTranslation((Vector3)x));
            var taskNodeRotate = new TaskVector4Control(iPtrPoke.GetNodeRotateTranslation(), Vector4.zero, ((EaseFunc)moveType).GetEase(), frame, x => iPtrPoke.SetNodeRotateTranslation((Vector3)x));

            float startTime = m_iPtrSequenceSystem.CurrentTime;
#if PC_UNLOCKED_FPS
            float endTime = startTime + 1.0f / PcPlatform.PcFrameClock.LogicRate * frame;
#else
            float endTime = startTime + 1.0f / Application.targetFrameRate * frame;
#endif

            taskTranslation.SetStartTime(startTime).SetEndTime(endTime).SetAdvanceMode(Task.AdvanceMode.Time);
            taskRotation.SetStartTime(startTime).SetEndTime(endTime).SetAdvanceMode(Task.AdvanceMode.Time);
            taskScale.SetStartTime(startTime).SetEndTime(endTime).SetAdvanceMode(Task.AdvanceMode.Time);
            taskNodeScale.SetStartTime(startTime).SetEndTime(endTime).SetAdvanceMode(Task.AdvanceMode.Time);
            taskNodeRotate.SetStartTime(startTime).SetEndTime(endTime).SetAdvanceMode(Task.AdvanceMode.Time);

            m_iPtrTaskManager.RegisterTask(taskTranslation, false);
            m_iPtrTaskManager.RegisterTask(taskRotation, false);
            m_iPtrTaskManager.RegisterTask(taskScale, false);
            m_iPtrTaskManager.RegisterTask(taskNodeScale, false);
            m_iPtrTaskManager.RegisterTask(taskNodeRotate, false);
        }
		private void SwapPokeModel(global::Dpr.Battle.Logic.BtlvPos vPos1, global::Dpr.Battle.Logic.BtlvPos vPos2) {
            if (m_iPtrCharacterSystem == null)
                return;

            var pokemons = m_iPtrCharacterSystem.Pokemons;
            var temp = pokemons[(int)vPos1];
            pokemons[(int)vPos1] = null;
            pokemons[(int)vPos1] = pokemons[(int)vPos2];
            pokemons[(int)vPos2] = null;
            pokemons[(int)vPos2] = temp;
        }
