		public global::Pml.PokePara.Size GetPokeSize(global::Dpr.Battle.View.Systems.BattleViewSystem.BattleViewSide side, bool isGPoke = false) {
            int pokeNum;
            switch (GetBattleRule())
            {
                case BtlRule.BTL_RULE_DOUBLE:
                    pokeNum = 2;
                    break;
                case BtlRule.BTL_RULE_RAID:
                    pokeNum = side == BattleViewSide.ENEMY_SIDE ? 1 : 4;
                    break;
                default:
                    pokeNum = 1;
                    break;
            }

            bool isExist = false;
            int size = 0;
            for (int i = 0; i < pokeNum; i++)
            {
                var model = GetPokeModel((BtlvPos)(i * 2 + (side == BattleViewSide.ENEMY_SIDE ? 1 : 0)));
                if (model == null || !model.IsEnable)
                    continue;

                size = Mathf.Max((int)model.GetSize(), size);
                isExist = true;
            }

            return isExist ? (Size)size : Size.M;
        }
