		private void GetDefaultTrainerPos(global::Dpr.Battle.Logic.BtlvPos vPos, ref global::UnityEngine.Vector3 pPos, ref int pDeg, bool isOrigin, global::Dpr.SequenceEditor.SEQ_DEF_DEFAULT_PLACEMENT placement) {
