		private bool CheckEgCamWazaStart() {
            SetComTargetReset();

            var atkPos = BtlPosToViewPos(m_wazaParam.m_atkPos);
            SetupWazaTarget(atkPos, BtlPosToViewPos(m_wazaParam.m_defPos), m_wazaParam.m_range);

            // IsGChange is called and its result discarded (01c8d168); both G flags end up false.
            _ = GetPokeModel(atkPos).IsGChange;
            m_wazaParam.m_isGShortWaza = false;
            m_wazaParam.m_isDefGPoke = IsDefGPoke();

            if (m_wazaParam.m_turnType == BtlvWazaEffect_TurnType.BTLV_WAZAEFF_INDEX_DEFAULT)
                m_wazaParam.m_turnType = GetUniqWazaSeqTurnType(atkPos, m_wazaParam.m_id, BtlvWazaEffect_TurnType.BTLV_WAZAEFF_INDEX_DEFAULT);

            bool? isNormalSeq = false;
            GetWazaSequencePath(ref m_wazaParam, ref isNormalSeq);
            return isNormalSeq.HasValue && isNormalSeq.Value;
        }
		private void SetupWazaTarget(global::Dpr.Battle.Logic.BtlvPos atkPos, global::Dpr.Battle.Logic.BtlvPos defPos, global::Pml.WazaData.WazaTarget wazaRange) {
            BtlvPos[] retArray = new BtlvPos[(int)BtlvPos.BTL_VPOS_NUM];
            BtlvPos[] posList = new BtlvPos[(int)BtlvPos.BTL_VPOS_NUM];
            for (int i = 0; i < (int)BtlvPos.BTL_VPOS_NUM; i++)
            {
                posList[i] = BtlvPos.BTL_VPOS_ERROR;
                retArray[i] = BtlvPos.BTL_VPOS_ERROR;
            }

            m_comTargetPoke[0] = atkPos;

            switch (wazaRange)
            {
                case WazaTarget.TARGET_OTHER_ALL:
                    SetupWazaTarget_AllFunc(atkPos, ref retArray, false);
                    break;

                case WazaTarget.TARGET_ENEMY_ALL:
                    SetupWazaTarget_AllFunc(atkPos, ref retArray, true);
                    break;

                case WazaTarget.TARGET_FRIEND_ALL:
                    m_comTargetPoke[1] = atkPos;
                    switch (GetBattleRule())
                    {
                        case BtlRule.BTL_RULE_SINGLE:
                            posList[0] = BtlvPos.BTL_VPOS_NEAR_1;
                            posList[1] = BtlvPos.BTL_VPOS_FAR_1;
                            break;

                        case BtlRule.BTL_RULE_DOUBLE:
                            posList[0] = BtlvPos.BTL_VPOS_NEAR_1;
                            posList[1] = BtlvPos.BTL_VPOS_FAR_1;
                            posList[2] = BtlvPos.BTL_VPOS_NEAR_2;
                            posList[3] = BtlvPos.BTL_VPOS_FAR_2;
                            break;

                        case BtlRule.BTL_RULE_RAID:
                            posList[0] = BtlvPos.BTL_VPOS_NEAR_1;
                            posList[1] = BtlvPos.BTL_VPOS_FAR_1;
                            posList[2] = BtlvPos.BTL_VPOS_NEAR_2;
                            posList[3] = BtlvPos.BTL_VPOS_NEAR_3;
                            posList[4] = BtlvPos.BTL_VPOS_NEAR_4;
                            break;
                    }

                    for (int i = 0; i < (int)BtlvPos.BTL_VPOS_NUM; i++)
                    {
                        if (posList[i] != BtlvPos.BTL_VPOS_ERROR && ViewPosToBtlSide(posList[i]) == ViewPosToBtlSide(atkPos))
                            retArray[i] = posList[i];
                    }
                    break;

                case WazaTarget.TARGET_ALL:
                case WazaTarget.TARGET_FIELD:
                case WazaTarget.TARGET_SIDE_ENEMY:
                case WazaTarget.TARGET_SIDE_FRIEND:
                    m_comTargetPoke[1] = atkPos;
                    switch (GetBattleRule())
                    {
                        case BtlRule.BTL_RULE_SINGLE:
                            posList[0] = BtlvPos.BTL_VPOS_NEAR_1;
                            posList[1] = BtlvPos.BTL_VPOS_FAR_1;
                            break;

                        case BtlRule.BTL_RULE_DOUBLE:
                            posList[0] = BtlvPos.BTL_VPOS_NEAR_1;
                            posList[1] = BtlvPos.BTL_VPOS_FAR_1;
                            posList[2] = BtlvPos.BTL_VPOS_NEAR_2;
                            posList[3] = BtlvPos.BTL_VPOS_FAR_2;
                            break;

                        case BtlRule.BTL_RULE_RAID:
                            posList[0] = BtlvPos.BTL_VPOS_NEAR_1;
                            posList[1] = BtlvPos.BTL_VPOS_FAR_1;
                            posList[2] = BtlvPos.BTL_VPOS_NEAR_2;
                            posList[3] = BtlvPos.BTL_VPOS_NEAR_3;
                            posList[4] = BtlvPos.BTL_VPOS_NEAR_4;
                            break;
                    }

                    for (int i = 0; i < (int)BtlvPos.BTL_VPOS_NUM; i++)
                    {
                        if (posList[i] == BtlvPos.BTL_VPOS_ERROR)
                            continue;

                        switch (wazaRange)
                        {
                            case WazaTarget.TARGET_ALL:
                            case WazaTarget.TARGET_FIELD:
                                retArray[i] = posList[i];
                                break;

                            case WazaTarget.TARGET_SIDE_ENEMY:
                            {
                                var side = ViewPosToBtlSide(posList[i]);
                                var atkSide = ViewPosToBtlSide(atkPos);
                                if (side != BtlSide.BTL_SIDE_NULL && side != atkSide)
                                {
                                    if (m_comTargetPoke[1] == atkPos)
                                        m_comTargetPoke[1] = posList[i];

                                    retArray[i] = posList[i];
                                }
                                break;
                            }

                            case WazaTarget.TARGET_SIDE_FRIEND:
                                if (ViewPosToBtlSide(posList[i]) == ViewPosToBtlSide(atkPos))
                                    retArray[i] = posList[i];
                                break;
                        }
                    }
                    break;

                default:
                    retArray[0] = defPos;
                    m_comTargetPoke[1] = defPos;
                    break;
            }

            int num = 0;
            for (int i = 0; i < (int)BtlvPos.BTL_VPOS_NUM; i++)
            {
                if (retArray[i] == BtlvPos.BTL_VPOS_ERROR)
                    continue;

                var pokeModel = m_iPtrCharacterSystem.GetPokemonModel(retArray[i]);
                if (pokeModel != null && pokeModel.IsEnable)
                    m_comTargetDamage[num++] = retArray[i];
            }

            var defModel = GetPokeModel(m_comTargetPoke[1]);
            if (defModel == null || !defModel.IsEnable)
                m_comTargetPoke[1] = m_comTargetDamage[0];

            m_comTargetTrainer[0] = (BtlvPos)GetBtlvPosToTrainerIdx(m_comTargetPoke[0]);
        }
		private void SetupWazaTarget_AllFunc(global::Dpr.Battle.Logic.BtlvPos atkPos, ref global::Dpr.Battle.Logic.BtlvPos[] retArray, bool enemyOnly) {
            switch (GetBattleRule())
            {
                case BtlRule.BTL_RULE_SINGLE:
                {
                    BtlvPos[] targetTable = new BtlvPos[] { BtlvPos.BTL_VPOS_FAR_1, BtlvPos.BTL_VPOS_NEAR_1 };
                    m_comTargetPoke[1] = targetTable[(int)atkPos];
                    retArray[0] = targetTable[(int)atkPos];
                    break;
                }
                case BtlRule.BTL_RULE_DOUBLE:
                {
                    BtlvPos[] targetTable = new BtlvPos[] { BtlvPos.BTL_VPOS_FAR_2, BtlvPos.BTL_VPOS_NEAR_2, BtlvPos.BTL_VPOS_FAR_1, BtlvPos.BTL_VPOS_NEAR_1 };
                    m_comTargetPoke[1] = targetTable[(int)atkPos];

                    BtlvPos[] allTable = new BtlvPos[] { BtlvPos.BTL_VPOS_NEAR_1, BtlvPos.BTL_VPOS_FAR_1, BtlvPos.BTL_VPOS_NEAR_2, BtlvPos.BTL_VPOS_FAR_2 };
                    for (int i = 0; i < allTable.Length; i++)
                    {
                        if (allTable[i] == atkPos)
                            continue;

                        if (enemyOnly && IsPlayerSide(allTable[i]) == IsPlayerSide(atkPos))
                            continue;

                        retArray[i] = allTable[i];
                    }
                    break;
                }
            }
        }
